  /**
   * Average Soil Surface Tempeature
   * Units: C
   */
  average_soil_surface_tempeature: number;
  /**
   * Soil Surface Temperature Amplitude 1
   * Units: deltaC
   */
  soil_surface_temperature_amplitude_1: number;
  /**
   * Soil Surface Temperature Amplitude 2
   * Units: deltaC
   */
  soil_surface_temperature_amplitude_2: number;
  /**
   * Phase Shift of Temperature Amplitude 1
   * Units: days
   */
  phase_shift_of_temperature_amplitude_1: number;
  /**
   * Phase Shift of Temperature Amplitude 2
   * Units: days
   */
