  /**
   * Soil Thermal Conductivity
   * Units: W/m-K
   * Default: 1.5
   */
  soil_thermal_conductivity?: number;
  /**
   * Soil Density
   * Units: kg/m3
   * Default: 2800
   */
  soil_density?: number;
  /**
   * Soil Specific Heat
   * Units: J/kg-K
   * Default: 850
   */
  soil_specific_heat?: number;
  /**
   * Soil Moisture Content Volume Fraction
   * Units: percent
   * Default: 30
   */
  soil_moisture_content_volume_fraction?: number;
  /**
   * Soil Moisture Content Volume Fraction at Saturation
   * Units: percent
   * Default: 50
   */
  soil_moisture_content_volume_fraction_at_saturation?: number;
  /** Undisturbed Ground Temperature Model Type */
  undisturbed_ground_temperature_model_type:
    | 'Site:GroundTemperature:Undisturbed:FiniteDifference'
    | 'Site:GroundTemperature:Undisturbed:KusudaAchenbach'
    | 'Site:GroundTemperature:Undisturbed:Xing';
  /** Undisturbed Ground Temperature Model Name */
  undisturbed_ground_temperature_model_name: string;
  /**
   * Evapotranspiration Ground Cover Parameter
   * This specifies the ground cover effects during evapotranspiration calculations.  The value roughly represents the following cases: = 0   : concrete or other solid, non-permeable ground surface material = 0.5 : short grass, much like a manicured lawn = 1   : standard reference state (12 cm grass) = 1.5 : wild growth
   * Default: 0.4
   */
  evapotranspiration_ground_cover_parameter?: number;
  /** Basement Floor Boundary Condition Model Name */
  basement_floor_boundary_condition_model_name: string;
  /**
   * Horizontal Insulation
   * This field specifies the presence of insulation beneath the basement floor.
   * Default: "No"
   */
  horizontal_insulation?: 'No' | 'Yes';
  /** Horizontal Insulation Material Name */
  horizontal_insulation_material_name?: string;
  /**
   * Horizontal Insulation Extents
   * This field specifies whether the horizontal insulation fully insulates the surface or is perimeter only insulation
   * Default: "Full"
   */
  horizontal_insulation_extents?: 'Full' | 'Perimeter';
  /**
   * Perimeter Horizontal Insulation Width
   * Width of horizontal perimeter insulation measured from foundation wall inside surface.
   * Units: m
   */
  perimeter_horizontal_insulation_width?: number;
  /**
   * Basement Wall Depth
   * Depth measured from ground surface.
   * Units: m
   */
  basement_wall_depth?: number;
  /** Basement Wall Boundary Condition Model Name */
  basement_wall_boundary_condition_model_name: string;
  /**
   * Vertical Insulation
   * Default: "No"
   */
  vertical_insulation?: 'No' | 'Yes';
  /** Basement Wall Vertical Insulation Material Name */
  basement_wall_vertical_insulation_material_name?: string;
  /**
   * Vertical Insulation Depth
   * Depth measured from the ground surface.
   * Units: m
   */
  vertical_insulation_depth?: number;
  /**
   * Simulation Timestep
   * This field specifies the basement domain simulation interval.
   * Default: "Hourly"
   */
