/**
 * Site:GroundReflectance
 * Specifies the ground reflectance values used to calculate ground reflected solar. The ground reflectance can be further modified when snow is on the ground by Site:GroundReflectance:SnowModifier.
 */
export interface Site_GroundReflectance {
  /**
   * January Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  january_ground_reflectance?: number;
  /**
   * February Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  february_ground_reflectance?: number;
  /**
   * March Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  march_ground_reflectance?: number;
  /**
   * April Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  april_ground_reflectance?: number;
  /**
   * May Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  may_ground_reflectance?: number;
  /**
   * June Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  june_ground_reflectance?: number;
  /**
   * July Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  july_ground_reflectance?: number;
  /**
   * August Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  august_ground_reflectance?: number;
  /**
   * September Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  september_ground_reflectance?: number;
  /**
   * October Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  october_ground_reflectance?: number;
  /**
   * November Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  november_ground_reflectance?: number;
  /**
   * December Ground Reflectance
   * Units: dimensionless
   * Default: 0.2
   */
  december_ground_reflectance?: number;
}

/**
 * Site:GroundReflectance:SnowModifier
 * Specifies ground reflectance multipliers when snow resident on the ground. These multipliers are applied to the "normal" ground reflectances specified in Site:GroundReflectance.
 */
export interface Site_GroundReflectance_SnowModifier {
  /**
   * Ground Reflected Solar Modifier
   * Value for modifying the "normal" ground reflectance when Snow is on ground when calculating the "Ground Reflected Solar Radiation Value" a value of 1.0 here uses the "normal" ground reflectance Ground Reflected Solar = (BeamSolar*CosSunZenith + DiffuseSolar)*GroundReflectance This would be further modified by the Snow Ground Reflectance Modifier when Snow was on the ground When Snow on ground, effective GroundReflectance is normal GroundReflectance*"Ground Reflectance Snow Modifier" Ground Reflectance achieved in this manner will be restricted to [0.0,1.0]
   * Default: 1
   */
  ground_reflected_solar_modifier?: number;
  /**
   * Daylighting Ground Reflected Solar Modifier
   * Value for modifying the "normal" daylighting ground reflectance when Snow is on ground when calculating the "Ground Reflected Solar Radiation Value" a value of 1.0 here uses the "normal" ground reflectance Ground Reflected Solar = (BeamSolar*CosSunZenith + DiffuseSolar)*GroundReflectance This would be further modified by the Snow Ground Reflectance Modifier when Snow was on the ground When Snow on ground, effective GroundReflectance is normal GroundReflectance*"Daylighting Ground Reflectance Snow Modifier" Ground Reflectance achieved in this manner will be restricted to [0.0,1.0]
   * Default: 1
   */
  daylighting_ground_reflected_solar_modifier?: number;
}

/**
 * Site:WaterMainsTemperature
 * Used to calculate water mains temperatures delivered by underground water main pipes. Water mains temperatures are a function of outdoor climate conditions and vary with time of year.
 */
export interface Site_WaterMainsTemperature {
  /**
   * Calculation Method
   * If calculation method is CorrelationFromWeatherFile, the two numeric input fields are ignored. Instead, EnergyPlus calculates them from weather file.
   * Default: "CorrelationFromWeatherFile"
   */
  calculation_method?: 'Correlation' | 'CorrelationFromWeatherFile' | 'Schedule';
  /** Temperature Schedule Name */
  temperature_schedule_name?: string;
  /**
   * Annual Average Outdoor Air Temperature
   * If calculation method is CorrelationFromWeatherFile or Schedule, this input field is ignored.
   * Units: C
   */
  annual_average_outdoor_air_temperature?: number;
  /**
   * Maximum Difference In Monthly Average Outdoor Air Temperatures
   * If calculation method is CorrelationFromWeatherFile or Schedule, this input field is ignored.
   * Units: deltaC
   */
  maximum_difference_in_monthly_average_outdoor_air_temperatures?: number;
}

/**
 * Site:Precipitation
 * Used to describe the amount of water precipitation at the building site. Precipitation includes both rain and the equivalent water content of snow.
 */
export interface Site_Precipitation {
  /** Precipitation Model Type */
  precipitation_model_type?: 'ScheduleAndDesignLevel';
  /**
   * Design Level for Total Annual Precipitation
   * meters of water per year used for design level
   * Units: m/yr
   */
  design_level_for_total_annual_precipitation?: number;
  /**
   * Precipitation Rates Schedule Name
   * Schedule values in meters of water per hour values should be non-negative
   */
  precipitation_rates_schedule_name?: string;
  /**
   * Average Total Annual Precipitation
   * meters of water per year from average weather statistics
   * Units: m/yr
   */
  average_total_annual_precipitation?: number;
}

/**
 * RoofIrrigation
 * Used to describe the amount of irrigation on the ecoroof surface over the course of the simulation runperiod.
 */
export interface RoofIrrigation {
  /**
   * Irrigation Model Type
   * SmartSchedule will not allow irrigation when soil is already moist. Current threshold set at 30% of saturation.
   */
  irrigation_model_type?: 'Schedule' | 'SmartSchedule';
  /**
   * Irrigation Rate Schedule Name
   * Schedule values in meters of water per hour values should be non-negative
   */
  irrigation_rate_schedule_name?: string;
  /**
   * Irrigation Maximum Saturation Threshold
   * Used with SmartSchedule to set the saturation level at which no irrigation is allowed.
   * Units: percent
   * Default: 40
   */
  irrigation_maximum_saturation_threshold?: number;
}

/**
 * Site:SolarAndVisibleSpectrum
 * If this object is omitted, the default solar and visible spectrum data will be used.
 */
export interface Site_SolarAndVisibleSpectrum {
  /**
   * Spectrum Data Method
   * The method specifies which of the solar and visible spectrum data to use in the calculations. Choices: Default - existing hard-wired spectrum data in EnergyPlus. UserDefined - user specified spectrum data referenced by the next two fields
   * Default: "Default"
   */
  spectrum_data_method?: 'Default' | 'UserDefined';
  /** Solar Spectrum Data Object Name */
  solar_spectrum_data_object_name?: string;
  /** Visible Spectrum Data Object Name */
  visible_spectrum_data_object_name?: string;
}

/**
 * Site:SpectrumData
 * Spectrum Data Type is followed by up to 107 sets of normal-incidence measured values of [wavelength, spectrum] for wavelengths covering the solar (0.25 to 2.5 microns) or visible spectrum (0.38 to 0.78 microns)
 */
export interface Site_SpectrumData {
  /** Spectrum Data Type */
  spectrum_data_type: 'Solar' | 'Visible';
  /**
   * Wavelength
   * Units: micron
   */
  wavelength?: number;
  /** Spectrum */
  spectrum?: number;
  /**
   * Wavelength
   * Units: micron
   */
  wavelength_1?: number;
  /** Spectrum */
  spectrum_2?: number;
  /** Repeating group: wavelength, spectrum */
  extensions?: ExtensibleGroup[];
}

/**
 * ScheduleTypeLimits
 * ScheduleTypeLimits specifies the data types and limits for the values contained in schedules
 */
export interface ScheduleTypeLimits {
  /**
   * Lower Limit Value
   * lower limit (real or integer) for the Schedule Type.  e.g. if fraction, this is 0.0
   */
  lower_limit_value?: number;
  /**
   * Upper Limit Value
   * upper limit (real or integer) for the Schedule Type.  e.g. if fraction, this is 1.0
   */
  upper_limit_value?: number;
  /**
   * Numeric Type
   * Numeric type is either Continuous (all numbers within the min and max are valid or Discrete (only integer numbers between min and max are valid.  (Could also allow REAL and INTEGER to mean the same things)
   */
  numeric_type?: 'Continuous' | 'Discrete';
  /**
   * Unit Type
   * Temperature (C or F) DeltaTemperature (C or F) PrecipitationRate (m/hr or ft/hr) Angle (degrees) Convection Coefficient (W/m2-K or Btu/sqft-hr-F) Activity Level (W/person) Velocity (m/s or ft/min) Capacity (W or Btu/h) Power (W)
   * Default: "Dimensionless"
   */
  unit_type?:
    | 'ActivityLevel'
    | 'Angle'
    | 'Availability'
    | 'Capacity'
    | 'Control'
    | 'ConvectionCoefficient'
    | 'DeltaTemperature'
    | 'Dimensionless'
    | 'Mode'
    | 'Percent'
    | 'Power'
    | 'PrecipitationRate'
    | 'Temperature'
    | 'Velocity';
}

