  /**
   * Viscosity Coefficient A
   * Used only if Gas Type = Custom
   * Units: kg/m-s
   */
  viscosity_coefficient_a?: number;
  /**
   * Viscosity Coefficient B
   * Used only if Gas Type = Custom
   * Units: kg/m-s-K
   */
  viscosity_coefficient_b?: number;
  /**
   * Viscosity Coefficient C
   * Used only if Gas Type = Custom
   * Units: kg/m-s-K2
   */
  viscosity_coefficient_c?: number;
  /**
   * Specific Heat Coefficient A
   * Used only if Gas Type = Custom
   * Units: J/kg-K
   */
  specific_heat_coefficient_a?: number;
  /**
   * Specific Heat Coefficient B
   * Used only if Gas Type = Custom
   * Units: J/kg-K2
   */
  specific_heat_coefficient_b?: number;
  /**
   * Specific Heat Coefficient C
   * Used only if Gas Type = Custom
   * Units: J/kg-K3
   */
