/**
 * Construction:WindowDataFile
 * Initiates search of the Window data file for a window called Name.
 */
export interface Construction_WindowDataFile {
  /**
   * File Name
   * default file name is "Window5DataFile.dat" limit on this field is 100 characters.
   */
  file_name?: string;
}

/**
 * GlobalGeometryRules
 * Specifies the geometric rules used to describe the input of surface vertices and daylighting reference points.
 */
export interface GlobalGeometryRules {
  /**
   * Starting Vertex Position
   * Specified as entry for a 4 sided surface/rectangle Surfaces are specified as viewed from outside the surface Shading surfaces as viewed from behind.  (towards what they are shading)
   */
  starting_vertex_position:
    'LowerLeftCorner' | 'LowerRightCorner' | 'UpperLeftCorner' | 'UpperRightCorner';
  /** Vertex Entry Direction */
  vertex_entry_direction: 'Clockwise' | 'Counterclockwise';
  /**
   * Coordinate System
   * Relative -- coordinates are entered relative to zone origin World -- all coordinates entered are "absolute" for this facility
   */
  coordinate_system: 'Relative' | 'World';
  /**
   * Daylighting Reference Point Coordinate System
   * Relative -- coordinates are entered relative to zone origin World -- all coordinates entered are "absolute" for this facility
   * Default: "Relative"
   */
  daylighting_reference_point_coordinate_system?: 'Relative' | 'World';
  /**
   * Rectangular Surface Coordinate System
   * Relative -- Starting corner is entered relative to zone origin World -- Starting corner is entered in "absolute"
   * Default: "Relative"
   */
  rectangular_surface_coordinate_system?: 'Relative' | 'World';
}

/**
 * GeometryTransform
 * Provides a simple method of altering the footprint geometry of a model. The intent is to provide a single parameter that can be used to reshape the building description contained in the rest of the input file.
 */
export interface GeometryTransform {
  /**
   * Plane of Transform
   * only current allowed value is "XY"
   * Default: "XY"
   */
  plane_of_transform?: 'XY';
  /**
   * Current Aspect Ratio
   * Aspect ratio of building as described in idf
   */
  current_aspect_ratio: number;
  /**
   * New Aspect Ratio
   * Aspect ratio to transform to during run
   */
  new_aspect_ratio: number;
}

/**
 * Zone
 * Defines a thermal zone of the building.
 */
export interface Zone {
  /**
   * Direction of Relative North
   * Units: deg
   * Default: 0
   */
  direction_of_relative_north?: number;
  /**
   * X Origin
   * Units: m
   * Default: 0
   */
  x_origin?: number;
  /**
   * Y Origin
   * Units: m
   * Default: 0
   */
  y_origin?: number;
  /**
   * Z Origin
   * Units: m
   * Default: 0
   */
  z_origin?: number;
  /**
   * Type
   * Default: 1
   */
  type?: number;
  /**
   * Multiplier
   * Default: 1
   */
  multiplier?: number;
  /**
   * Ceiling Height
   * If this field is 0.0, negative or autocalculate, then the average height of the zone is automatically calculated and used in subsequent calculations. If this field is positive, then the number entered here will be used. Note that the Zone Ceiling Height is the distance from the Floor to the Ceiling in the Zone, not an absolute height from the ground.
   * Units: m
   * Default: "Autocalculate"
   */
  ceiling_height?: number | 'Autosize' | 'Autocalculate';
  /**
   * Volume
   * If this field is 0.0, negative or autocalculate, then the volume of the zone is automatically calculated and used in subsequent calculations. If this field is positive, then the number entered here will be used.
   * Units: m3
   * Default: "Autocalculate"
   */
  volume?: number | 'Autosize' | 'Autocalculate';
  /**
   * Floor Area
   * If this field is 0.0, negative or autocalculate, then the floor area of the zone is automatically calculated and used in subsequent calculations. If this field is positive, then the number entered here will be used.
   * Units: m2
   * Default: "Autocalculate"
   */
  floor_area?: number | 'Autosize' | 'Autocalculate';
  /**
   * Zone Inside Convection Algorithm
   * Will default to same value as SurfaceConvectionAlgorithm:Inside object setting this field overrides the default SurfaceConvectionAlgorithm:Inside for this zone Simple = constant natural convection (ASHRAE) TARP = variable natural convection based on temperature difference (ASHRAE) CeilingDiffuser = ACH based forced and mixed convection correlations for ceiling diffuser configuration with simple natural convection limit AdaptiveConvectionAlgorithm = dynamic selection of convection models based on conditions TrombeWall = variable natural convection in an enclosed rectangular cavity
   */
  zone_inside_convection_algorithm?:
    'AdaptiveConvectionAlgorithm' | 'CeilingDiffuser' | 'Simple' | 'TARP' | 'TrombeWall';
  /**
   * Zone Outside Convection Algorithm
   * Will default to same value as SurfaceConvectionAlgorithm:Outside object setting this field overrides the default SurfaceConvectionAlgorithm:Outside for this zone SimpleCombined = Combined radiation and convection coefficient using simple ASHRAE model TARP = correlation from models developed by ASHRAE, Walton, and Sparrow et. al. MoWiTT = correlation from measurements by Klems and Yazdanian for smooth surfaces DOE-2 = correlation from measurements by Klems and Yazdanian for rough surfaces AdaptiveConvectionAlgorithm = dynamic selection of correlations based on conditions
   */
  zone_outside_convection_algorithm?:
    'AdaptiveConvectionAlgorithm' | 'DOE-2' | 'MoWiTT' | 'SimpleCombined' | 'TARP';
  /**
   * Part of Total Floor Area
   * Default: "Yes"
   */
  part_of_total_floor_area?: 'No' | 'Yes';
}

/**
 * ZoneList
 * Defines a list of thermal zones which can be referenced as a group. The ZoneList name may be used elsewhere in the input to apply a parameter to all zones in the list. ZoneLists can be used effectively with the following objects: People, Lights, ElectricEquipment, GasEquipment, HotWaterEquipment, ZoneInfiltration:DesignFlowRate, ZoneVentilation:DesignFlowRate, Sizing:Zone, ZoneControl:Thermostat, and others.
 */
export interface ZoneList {
  /** Repeating group: zone_name */
  zones?: ExtensibleGroup[];
}

/**
 * ZoneGroup
 * Adds a multiplier to a ZoneList. This can be used to reduce the amount of input necessary for simulating repetitive structures, such as the identical floors of a multi-story building.
 */
export interface ZoneGroup {
  /** Zone List Name */
  zone_list_name: string;
  /**
   * Zone List Multiplier
   * Default: 1
   */
  zone_list_multiplier?: number;
}

/**
 * BuildingSurface:Detailed
 * Allows for detailed entry of building heat transfer surfaces.  Does not include subsurfaces such as windows or doors.
 */
export interface BuildingSurface_Detailed {
  /** Surface Type */
  surface_type: 'Ceiling' | 'Floor' | 'Roof' | 'Wall';
  /**
   * Construction Name
   * To be matched with a construction in this input file
   */
  construction_name: string;
  /**
   * Zone Name
   * Zone the surface is a part of
   */
  zone_name: string;
  /** Outside Boundary Condition */
  outside_boundary_condition:
    | 'Adiabatic'
    | 'Foundation'
    | 'Ground'
    | 'GroundBasementPreprocessorAverageFloor'
    | 'GroundBasementPreprocessorAverageWall'
    | 'GroundBasementPreprocessorLowerWall'
    | 'GroundBasementPreprocessorUpperWall'
    | 'GroundFCfactorMethod'
    | 'GroundSlabPreprocessorAverage'
    | 'GroundSlabPreprocessorCore'
    | 'GroundSlabPreprocessorPerimeter'
    | 'OtherSideCoefficients'
    | 'OtherSideConditionsModel'
    | 'Outdoors'
    | 'Surface'
    | 'Zone';
  /**
   * Outside Boundary Condition Object
   * Non-blank only if the field Outside Boundary Condition is Surface, Zone, OtherSideCoefficients or OtherSideConditionsModel If Surface, specify name of corresponding surface in adjacent zone or specify current surface name for internal partition separating like zones If Zone, specify the name of the corresponding zone and the program will generate the corresponding interzone surface If Foundation, specify the name of the corresponding Foundation object and the program will calculate the heat transfer appropriately If OtherSideCoefficients, specify name of SurfaceProperty:OtherSideCoefficients If OtherSideConditionsModel, specify name of SurfaceProperty:OtherSideConditionsModel
   */
  outside_boundary_condition_object?: string;
  /**
   * Sun Exposure
   * Default: "SunExposed"
   */
  sun_exposure?: 'NoSun' | 'SunExposed';
  /**
   * Wind Exposure
   * Default: "WindExposed"
   */
  wind_exposure?: 'NoWind' | 'WindExposed';
  /**
   * View Factor to Ground
   * From the exterior of the surface Unused if one uses the "reflections" options in Solar Distribution in Building input unless a DaylightingDevice:Shelf or DaylightingDevice:Tubular object has been specified. autocalculate will automatically calculate this value from the tilt of the surface
   * Default: "Autocalculate"
   */
  view_factor_to_ground?: number | 'Autosize' | 'Autocalculate';
  /**
   * Number of Vertices
   * shown with 120 vertex coordinates -- extensible object "extensible" -- duplicate last set of x,y,z coordinates (last 3 fields), remembering to remove ; from "inner" fields. for clarity in any error messages, renumber the fields as well. (and changing z terminator to a comma "," for all but last one which needs a semi-colon ";") vertices are given in GlobalGeometryRules coordinates -- if relative, all surface coordinates are "relative" to the Zone Origin.  If world, then building and zone origins are used for some internal calculations, but all coordinates are given in an "absolute" system.
   * Default: "Autocalculate"
   */
  number_of_vertices?: number | 'Autosize' | 'Autocalculate';
  /** Repeating group: vertex_x_coordinate, vertex_y_coordinate, vertex_z_coordinate */
  vertices?: ExtensibleGroup[];
}

