/**
 * SurfaceConvectionAlgorithm:Inside:UserCurve
 * Used to describe a custom model equation for surface convection heat transfer coefficient If more than one curve is referenced they are all used and added together.
 */
export interface SurfaceConvectionAlgorithm_Inside_UserCurve {
  /**
   * Reference Temperature for Convection Heat Transfer
   * Controls which temperature is differenced from surface temperature when using the Hc value
   */
  reference_temperature_for_convection_heat_transfer?:
    'AdjacentAirTemperature' | 'MeanAirTemperature' | 'SupplyAirTemperature';
  /**
   * Hc Function of Temperature Difference Curve Name
   * Curve's "x" is absolute value of delta-T (Surface temperature minus reference temperature, (C))
   */
  hc_function_of_temperature_difference_curve_name?: string;
  /**
   * Hc Function of Temperature Difference Divided by Height Curve Name
   * Curve's "x" is absolute value of delta-T/Height (Surface temp minus Air temp)/(vertical length scale), (C/m) when used for an inside face the vertical length scale is the zone's interior height
   */
  hc_function_of_temperature_difference_divided_by_height_curve_name?: string;
  /**
   * Hc Function of Air Change Rate Curve Name
   * Curve's "x" is mechanical ACH (Air Changes per hour from mechanical air system), (1/hr)
   */
  hc_function_of_air_change_rate_curve_name?: string;
  /**
   * Hc Function of Air System Volume Flow Rate Divided by Zone Perimeter Length Curve Name
   * Curve's "x" is mechanical system air flow rate (m3/s) divided by zone's length along exterior walls (m).
   */
  hc_function_of_air_system_volume_flow_rate_divided_by_zone_perimeter_length_curve_name?: string;
}

/**
 * SurfaceConvectionAlgorithm:Outside:UserCurve
 * Used to describe a custom model equation for surface convection heat transfer coefficient If more than one curve is referenced they are all used and added together.
 */
export interface SurfaceConvectionAlgorithm_Outside_UserCurve {
  /**
   * Wind Speed Type for Curve
   * Default: "HeightAdjust"
   */
  wind_speed_type_for_curve?:
    'HeightAdjust' | 'ParallelComponent' | 'ParallelComponentHeightAdjust' | 'WeatherFile';
  /**
   * Hf Function of Wind Speed Curve Name
   * Curve's "x" is wind speed of the type determined in the previous field (m/s)
   */
  hf_function_of_wind_speed_curve_name?: string;
  /**
   * Hn Function of Temperature Difference Curve Name
   * Curve's "x" is absolute value of delta-T (Surface temperature minus air temperature, (C))
   */
  hn_function_of_temperature_difference_curve_name?: string;
  /**
   * Hn Function of Temperature Difference Divided by Height Curve Name
   * Curve's "x" is absolute value of delta-T/Height (Surface temp minus Air temp)/(vertical length scale), (C/m) when used for an outside face the vertical length scale is the exterior facade's overall height
   */
  hn_function_of_temperature_difference_divided_by_height_curve_name?: string;
}

