/**
 * RoomAirSettings:OneNodeDisplacementVentilation
 * The Mundt model for displacement ventilation
 */
export interface RoomAirSettings_OneNodeDisplacementVentilation {
  /** Zone Name */
  zone_name: string;
  /** Fraction of Convective Internal Loads Added to Floor Air */
  fraction_of_convective_internal_loads_added_to_floor_air?: number;
  /** Fraction of Infiltration Internal Loads Added to Floor Air */
  fraction_of_infiltration_internal_loads_added_to_floor_air?: number;
}

/**
 * RoomAirSettings:ThreeNodeDisplacementVentilation
 * The UCSD model for Displacement Ventilation
 */
export interface RoomAirSettings_ThreeNodeDisplacementVentilation {
  /**
   * Zone Name
   * Name of Zone being described. Any existing zone name
   */
  zone_name: string;
  /**
   * Gain Distribution Schedule Name
   * Distribution of the convective heat gains between the occupied and mixed zones. 0<= Accepted Value <= 1. In the DV model 1 means all convective gains in the lower layer.
   */
  gain_distribution_schedule_name: string;
  /**
   * Number of Plumes per Occupant
   * Used only in the UCSD displacement ventilation model. Effective number of separate plumes per occupant in the occupied zone. Plumes that merge together in the occupied zone count as one.
   * Default: 1
   */
  number_of_plumes_per_occupant?: number;
  /**
   * Thermostat Height
   * Height of thermostat/temperature control sensor above floor
   * Units: m
   * Default: 1.1
   */
  thermostat_height?: number;
  /**
   * Comfort Height
   * Height at which air temperature is calculated for comfort purposes
   * Units: m
   * Default: 1.1
   */
  comfort_height?: number;
  /**
   * Temperature Difference Threshold for Reporting
   * Minimum temperature difference between predicted upper and lower layer temperatures above which DV auxiliary outputs are calculated. These outputs are 'DV Transition Height', 'DV Fraction Min Recommended Flow Rate' 'DV Average Temp Gradient' and 'DV Maximum Temp Gradient'.  They are set to negative values when the temperature difference is less than the threshold and the output 'DV Zone Is Mixed' is set to 1
   * Units: deltaC
   * Default: 0.4
   */
  temperature_difference_threshold_for_reporting?: number;
}

/**
 * RoomAirSettings:CrossVentilation
 * This UCSD Cross Ventilation Room Air Model provides a simple model for heat transfer and vertical temperature profile prediction in cross ventilated rooms. The model distinguishes two regions in the room, the main jet region and the recirculations, and predicts characteristic airflow velocities and average air temperatures. Used with RoomAirModelType = CrossVentilation.
 */
export interface RoomAirSettings_CrossVentilation {
  /**
   * Zone Name
   * Name of Zone being described. Any existing zone name
   */
  zone_name: string;
  /**
   * Gain Distribution Schedule Name
   * Distribution of the convective heat gains between the jet and recirculation zones. 0<= Accepted Value <= 1. In the CV model 1 means all convective gains in the jet region.
   */
  gain_distribution_schedule_name: string;
  /**
   * Airflow Region Used for Thermal Comfort Evaluation
   * Required field whenever thermal comfort is predicted defines Air temperature and Airflow velocity that will be used in the Fanger model conditions must refer to one of the two regions: jet or recirculation
   */
  airflow_region_used_for_thermal_comfort_evaluation?: 'Jet' | 'Recirculation';
}

/**
 * RoomAirSettings:UnderFloorAirDistributionInterior
 * This Room Air Model is applicable to interior spaces that are served by an underfloor air distribution system. The dominant sources of heat gain should be from people, equipment, and other localized sources located in the occupied part of the room. The model should be used with caution in zones which have large heat gains or losses through exterior walls or windows or which have considerable direct solar gain. Used with RoomAirModelType = UnderFloorAirDistributionInterior.
 */
export interface RoomAirSettings_UnderFloorAirDistributionInterior {
  /**
   * Zone Name
   * Name of Zone with underfloor air distribution
   */
  zone_name: string;
  /**
   * Number of Diffusers
   * Total number of diffusers in this zone
   * Default: "Autocalculate"
   */
  number_of_diffusers?: number | 'Autosize' | 'Autocalculate';
  /**
   * Power per Plume
   * Units: W
   * Default: "Autocalculate"
   */
  power_per_plume?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Effective Area of Diffuser
   * Units: m2
   * Default: "Autocalculate"
   */
  design_effective_area_of_diffuser?: number | 'Autosize' | 'Autocalculate';
  /**
   * Diffuser Slot Angle from Vertical
   * Units: deg
   * Default: "Autocalculate"
   */
  diffuser_slot_angle_from_vertical?: number | 'Autosize' | 'Autocalculate';
  /**
   * Thermostat Height
   * Height of thermostat/temperature control sensor above floor
   * Units: m
   * Default: 1.2
   */
  thermostat_height?: number;
  /**
   * Comfort Height
   * Height at which air temperature is calculated for comfort purposes
   * Units: m
   * Default: 1.1
   */
  comfort_height?: number;
  /**
   * Temperature Difference Threshold for Reporting
   * Minimum temperature difference between predicted upper and lower layer temperatures above which UFAD auxiliary outputs are calculated. These outputs are 'UF Transition Height' and 'UF Average Temp Gradient'.  They are set to zero values when the temperature difference is less than the threshold and the output 'UF Zone Is Mixed' is set to 1
   * Units: deltaC
   * Default: 0.4
   */
  temperature_difference_threshold_for_reporting?: number;
  /**
   * Floor Diffuser Type
   * Default: "Swirl"
   */
  floor_diffuser_type?: 'Custom' | 'HorizontalSwirl' | 'LinearBarGrille' | 'Swirl' | 'VariableArea';
  /**
   * Transition Height
   * user-specified height above floor of boundary between occupied and upper subzones
   * Units: m
   * Default: 1.7
   */
  transition_height?: number | 'Autosize' | 'Autocalculate';
  /**
   * Coefficient A
   * Coefficient A in Formula Kc = A*Gamma**B + C + D*Gamma + E*Gamma**2 Kc is the fraction of the total zone load attributable to the lower subzone
   * Default: "Autocalculate"
   */
  coefficient_a?: number | 'Autosize' | 'Autocalculate';
  /**
   * Coefficient B
   * Coefficient B in Formula Kc = A*Gamma**B + C + D*Gamma + E*Gamma**2 Kc is the fraction of the total zone load attributable to the lower subzone
   * Default: "Autocalculate"
   */
  coefficient_b?: number | 'Autosize' | 'Autocalculate';
  /**
   * Coefficient C
   * Coefficient C in Formula Kc = A*Gamma**B + C + D*Gamma + E*Gamma**2 Kc is the fraction of the total zone load attributable to the lower subzone
   * Default: "Autocalculate"
   */
  coefficient_c?: number | 'Autosize' | 'Autocalculate';
  /**
   * Coefficient D
   * Coefficient D in Formula Kc = A*Gamma**B + C + D*Gamma + E*Gamma**2 Kc is the fraction of the total zone load attributable to the lower subzone
   * Default: "Autocalculate"
   */
  coefficient_d?: number | 'Autosize' | 'Autocalculate';
  /**
   * Coefficient E
   * Coefficient E in Formula Kc = A*Gamma**B + C + D*Gamma + E*Gamma**2 Kc is the fraction of the total zone load attributable to the lower subzone
   * Default: "Autocalculate"
   */
  coefficient_e?: number | 'Autosize' | 'Autocalculate';
}

