/**
 * People
 * Sets internal gains and contaminant rates for occupants in the zone. If you use a ZoneList in the Zone or ZoneList name field then this definition applies to all the zones in the ZoneList.
 */
export interface People {
  /** Zone or ZoneList Name */
  zone_or_zonelist_name: string;
  /**
   * Number of People Schedule Name
   * units in schedule should be fraction applied to number of people (0.0 - 1.0)
   */
  number_of_people_schedule_name: string;
  /**
   * Number of People Calculation Method
   * The entered calculation method is used to create the maximum number of people for this set of attributes (i.e. sensible fraction, schedule, etc) Choices: People -- simply enter number of occupants. People per Zone Floor Area -- enter the number to apply.  Value * Floor Area = Number of people Zone Floor Area per Person -- enter the number to apply.  Floor Area / Value = Number of people
   * Default: "People"
   */
  number_of_people_calculation_method?: 'Area/Person' | 'People' | 'People/Area';
  /** Number of People */
  number_of_people?: number;
  /**
   * People per Zone Floor Area
   * Units: person/m2
   */
  people_per_zone_floor_area?: number;
  /**
   * Zone Floor Area per Person
   * Units: m2/person
   */
  zone_floor_area_per_person?: number;
  /**
   * Fraction Radiant
   * This is radiant fraction of the sensible heat released by people in a zone. This value will be multiplied by the total sensible heat released by people yields the amount of long wavelength radiation gain from people in a zone. Default value is 0.30.
   * Default: 0.3
   */
  fraction_radiant?: number;
  /**
   * Sensible Heat Fraction
   * if input, overrides program calculated sensible/latent split
   * Default: "Autocalculate"
   */
  sensible_heat_fraction?: number | 'Autosize' | 'Autocalculate';
  /**
   * Activity Level Schedule Name
   * Note that W has to be converted to mets in TC routine units in schedule are W/person
   */
  activity_level_schedule_name: string;
  /**
   * Carbon Dioxide Generation Rate
   * CO2 generation rate per unit of activity level. The default value is obtained from ASHRAE Std 62.1 at 0.0084 cfm/met/person over the general adult population.
   * Units: m3/s-W
   * Default: 3.82e-8
   */
  carbon_dioxide_generation_rate?: number;
  /**
   * Enable ASHRAE 55 Comfort Warnings
   * Default: "No"
   */
  enable_ashrae_55_comfort_warnings?: 'No' | 'Yes';
  /**
   * Mean Radiant Temperature Calculation Type
   * optional (only required for thermal comfort runs)
   * Default: "ZoneAveraged"
   */
  mean_radiant_temperature_calculation_type?: 'AngleFactor' | 'SurfaceWeighted' | 'ZoneAveraged';
  /**
   * Surface Name/Angle Factor List Name
   * optional (only required for runs of thermal comfort models: Fanger, Pierce and KSU)
   */
  surface_name_angle_factor_list_name?: string;
  /**
   * Work Efficiency Schedule Name
   * units in schedule are 0.0 to 1.0 optional (only required for runs of thermal comfort models: Fanger, Pierce and KSU)
   */
  work_efficiency_schedule_name?: string;
  /**
   * Clothing Insulation Calculation Method
   * Default: "ClothingInsulationSchedule"
   */
  clothing_insulation_calculation_method?:
    'CalculationMethodSchedule' | 'ClothingInsulationSchedule' | 'DynamicClothingModelASHRAE55';
  /**
   * Clothing Insulation Calculation Method Schedule Name
   * a schedule value of 1 for the Scheduled method, and 2 for the DynamicClothingModelASHRAE55 method
   */
  clothing_insulation_calculation_method_schedule_name?: string;
  /**
   * Clothing Insulation Schedule Name
   * use "Clo" from ASHRAE or Thermal Comfort guides optional (only required for runs of thermal comfort models: Fanger, Pierce and KSU)
   */
  clothing_insulation_schedule_name?: string;
  /**
   * Air Velocity Schedule Name
   * units in the schedule are m/s optional (only required for runs of thermal comfort models: Fanger, Pierce and KSU)
   */
  air_velocity_schedule_name?: string;
  /**
   * Thermal Comfort Model 1 Type
   * optional (only needed for people thermal comfort results reporting)
   */
  thermal_comfort_model_1_type?: 'AdaptiveASH55' | 'AdaptiveCEN15251' | 'Fanger' | 'KSU' | 'Pierce';
  /**
   * Thermal Comfort Model 2 Type
   * optional (second type of thermal comfort model and results reporting)
   */
  thermal_comfort_model_2_type?: 'AdaptiveASH55' | 'AdaptiveCEN15251' | 'Fanger' | 'KSU' | 'Pierce';
  /**
   * Thermal Comfort Model 3 Type
   * optional (third thermal comfort model and report type)
   */
  thermal_comfort_model_3_type?: 'AdaptiveASH55' | 'AdaptiveCEN15251' | 'Fanger' | 'KSU' | 'Pierce';
  /**
   * Thermal Comfort Model 4 Type
   * optional (fourth thermal comfort model and report type)
   */
  thermal_comfort_model_4_type?: 'AdaptiveASH55' | 'AdaptiveCEN15251' | 'Fanger' | 'KSU' | 'Pierce';
  /**
   * Thermal Comfort Model 5 Type
   * optional (fifth thermal comfort model and report type)
   */
  thermal_comfort_model_5_type?: 'AdaptiveASH55' | 'AdaptiveCEN15251' | 'Fanger' | 'KSU' | 'Pierce';
}

