/**
 * Lights
 * Sets internal gains for lights in the zone. If you use a ZoneList in the Zone or ZoneList name field then this definition applies to all the zones in the ZoneList.
 */
export interface Lights {
  /** Zone or ZoneList Name */
  zone_or_zonelist_name: string;
  /**
   * Schedule Name
   * units in schedule should be fraction applied to design level of lights, generally (0.0 - 1.0)
   */
  schedule_name: string;
  /**
   * Design Level Calculation Method
   * The entered calculation method is used to create the maximum amount of lights for this set of attributes Choices: LightingLevel => Lighting Level -- simply enter watts of lights Watts/Area => Watts per Zone Floor Area -- enter the number to apply.  Value * Floor Area = Lights Watts/Person => Watts per Person -- enter the number to apply.  Value * Occupants = Lights
   * Default: "LightingLevel"
   */
  design_level_calculation_method?: 'LightingLevel' | 'Watts/Area' | 'Watts/Person';
  /**
   * Lighting Level
   * Units: W
   */
  lighting_level?: number;
  /**
   * Watts per Zone Floor Area
   * Units: W/m2
   */
  watts_per_zone_floor_area?: number;
  /**
   * Watts per Person
   * Units: W/person
   */
  watts_per_person?: number;
  /**
   * Return Air Fraction
   * Used only for sizing calculation if return-air-fraction coefficients are specified.
   * Default: 0
   */
  return_air_fraction?: number;
  /**
   * Fraction Radiant
   * Default: 0
   */
  fraction_radiant?: number;
  /**
   * Fraction Visible
   * Default: 0
   */
  fraction_visible?: number;
  /**
   * Fraction Replaceable
   * For Daylighting:Controls must be 0 or 1:  0 = no dimming control, 1 = full dimming control
   * Default: 1
   */
  fraction_replaceable?: number;
  /**
   * End-Use Subcategory
   * Any text may be used here to categorize the end-uses in the ABUPS End Uses by Subcategory table.
   * Default: "General"
   */
  end_use_subcategory?: string;
  /**
   * Return Air Fraction Calculated from Plenum Temperature
   * Default: "No"
   */
  return_air_fraction_calculated_from_plenum_temperature?: 'No' | 'Yes';
  /**
   * Return Air Fraction Function of Plenum Temperature Coefficient 1
   * Used only if Return Air Fraction Is Calculated from Plenum Temperature = Yes Equation is Return Air Fraction = Coefficient#1 - Coefficient#2 X PlenumTemp(degC)
   * Default: 0
   */
  return_air_fraction_function_of_plenum_temperature_coefficient_1?: number;
  /**
   * Return Air Fraction Function of Plenum Temperature Coefficient 2
   * Used only if Return Air Fraction Is Calculated from Plenum Temperature = Yes Equation is Return Air Fraction = Coefficient#1 - Coefficient#2 X PlenumTemp(degC)
   * Units: 1/K
   * Default: 0
   */
  return_air_fraction_function_of_plenum_temperature_coefficient_2?: number;
  /**
   * Return Air Heat Gain Node Name
   * Name of the return air node for this heat gain. If left blank, defaults to the first return air node for the zone. Leave this field blank when using a ZoneList name.
   */
  return_air_heat_gain_node_name?: string;
}

