/**
 * AirflowNetwork:ZoneControl:PressureController
 * This object is used to control a zone to a specified indoor pressure using the AirflowNetwork model. The specified pressure setpoint is used to control the zone exhaust fan flow rate in a controlled zone or the relief air flow rate in an air loop.
 */
export interface AirflowNetwork_ZoneControl_PressureController {
  /** Control Zone Name */
  control_zone_name: string;
  /**
   * Control Object Type
   * The current selection is AirflowNetwork:MultiZone:Component:ZoneExhaustFan or AirflowNetwork:Distribution:Component:ReliefAirFlow.
   */
  control_object_type:
    | 'AirflowNetwork:Distribution:Component:ReliefAirFlow'
    | 'AirflowNetwork:MultiZone:Component:ZoneExhaustFan';
  /**
   * Control Object Name
   * Control names are names of individual control objects
   */
  control_object_name: string;
  /**
   * Pressure Control Availability Schedule Name
   * Availability schedule name for pressure controller. Schedule value > 0 means the pressure controller is enabled. If this field is blank, then pressure controller is always enabled.
   */
  pressure_control_availability_schedule_name?: string;
  /** Pressure Setpoint Schedule Name */
  pressure_setpoint_schedule_name: string;
}

/**
 * AirflowNetwork:Distribution:Node
 * This object represents an air distribution node in the AirflowNetwork model.
 */
export interface AirflowNetwork_Distribution_Node {
  /**
   * Component Name or Node Name
   * Designates node names defined in another object. The node name may occur in air branches. Enter a node name to represent a node already defined in an air loop. Leave this field blank if the Node or Object Type field below is entered as AirLoopHVAC:ZoneMixer, AirLoopHVAC:ZoneSplitter, AirLoopHVAC:OutdoorAirSystem, or Other.
   */
  component_name_or_node_name?: string;
  /**
   * Component Object Type or Node Type
   * Designates Node type for the Node or Component Name defined in the field above. AirLoopHVAC:ZoneMixer -- Represents a AirLoopHVAC:ZoneMixer object. AirLoopHVAC:ZoneSplitter -- Represents a AirLoopHVAC:ZoneSplitter object. AirLoopHVAC:OutdoorAirSystem -- Represents an AirLoopHVAC:OutdoorAirSystem object. OAMixerOutdoorAirStreamNode -- Represents an external node used in the OutdoorAir:Mixer OutdoorAir:NodeList -- Represents an external node when a heat exchanger is used before the OutdoorAir:Mixer OutdoorAir:Node -- Represents an external node when a heat exchanger is used before the OutdoorAir:Mixer Other -- none of the above, the Node name already defined in the previous field is part of an air loop.
   * Default: "Other"
   */
  component_object_type_or_node_type?:
    | 'AirLoopHVAC:OutdoorAirSystem'
    | 'AirLoopHVAC:ZoneMixer'
    | 'AirLoopHVAC:ZoneSplitter'
    | 'OAMixerOutdoorAirStreamNode'
    | 'Other'
    | 'OutdoorAir:Node'
    | 'OutdoorAir:NodeList';
  /**
   * Node Height
   * Enter the reference height used to calculate the relative pressure.
   * Units: m
   * Default: 0
   */
  node_height?: number;
}

/**
 * AirflowNetwork:Distribution:Component:Leak
 * This object defines the characteristics of a supply or return air leak.
 */
export interface AirflowNetwork_Distribution_Component_Leak {
  /**
   * Air Mass Flow Coefficient
   * Defined at 1 Pa pressure difference across this component. Enter the coefficient used in the following equation: Mass Flow Rate = Air Mass Flow Coefficient * (dP)^Air Mass Flow Exponent
   * Units: kg/s
   */
  air_mass_flow_coefficient: number;
  /**
   * Air Mass Flow Exponent
   * Enter the exponent used in the following equation: Mass Flow Rate = Air Mass Flow Coefficient * (dP)^Air Mass Flow Exponent
   * Units: dimensionless
   * Default: 0.65
   */
  air_mass_flow_exponent?: number;
}

/**
 * AirflowNetwork:Distribution:Component:LeakageRatio
 * This object is used to define supply and return air leaks with respect to the fan's maximum air flow rate.
 */
export interface AirflowNetwork_Distribution_Component_LeakageRatio {
  /**
   * Effective Leakage Ratio
   * Defined as a ratio of leak flow rate to the maximum flow rate.
   * Units: dimensionless
   */
  effective_leakage_ratio?: number;
  /**
   * Maximum Flow Rate
   * Enter the maximum air flow rate in this air loop.
   * Units: m3/s
   */
  maximum_flow_rate: number;
  /**
   * Reference Pressure Difference
   * Enter the pressure corresponding to the Effective leakage ratio entered above.
   * Units: Pa
   */
  reference_pressure_difference: number;
  /**
   * Air Mass Flow Exponent
   * Enter the exponent used in the air mass flow equation.
   * Units: dimensionless
   * Default: 0.65
   */
  air_mass_flow_exponent?: number;
}

/**
 * AirflowNetwork:Distribution:Component:Duct
 * This object defines the relationship between pressure and air flow through the duct.
 */
export interface AirflowNetwork_Distribution_Component_Duct {
  /**
   * Duct Length
   * Enter the length of the duct.
   * Units: m
   */
  duct_length: number;
  /**
   * Hydraulic Diameter
   * Enter the hydraulic diameter of the duct. Hydraulic diameter is defined as 4 multiplied by cross section area divided by perimeter
   * Units: m
   */
  hydraulic_diameter: number;
  /**
   * Cross Section Area
   * Enter the cross section area of the duct.
   * Units: m2
   */
  cross_section_area: number;
  /**
   * Surface Roughness
   * Enter the inside surface roughness of the duct.
   * Units: m
   * Default: 0.0009
   */
  surface_roughness?: number;
  /**
   * Coefficient for Local Dynamic Loss Due to Fitting
   * Enter the coefficient used to calculate dynamic losses of fittings (e.g. elbows).
   * Units: dimensionless
   * Default: 0
   */
  coefficient_for_local_dynamic_loss_due_to_fitting?: number;
  /**
   * Heat Transmittance Coefficient (U-Factor) for Duct Wall Construction
   * conduction only Default value of 0.943 is equivalent to 1.06 m2-K/W (R6) duct insulation.
   * Units: W/m2-K
   * Default: 0.943
   */
  heat_transmittance_coefficient_u_factor_for_duct_wall_construction?: number;
  /**
   * Overall Moisture Transmittance Coefficient from Air to Air
   * Enter the overall moisture transmittance coefficient including moisture film coefficients at both surfaces.
   * Units: kg/m2
   * Default: 0.001
   */
  overall_moisture_transmittance_coefficient_from_air_to_air?: number;
  /**
   * Outside Convection Coefficient
   * optional. convection coefficient calculated automatically, unless specified
   * Units: W/m2-K
   */
  outside_convection_coefficient?: number;
  /**
   * Inside Convection Coefficient
   * optional. convection coefficient calculated automatically, unless specified
   * Units: W/m2-K
   */
  inside_convection_coefficient?: number;
}

/**
 * AirflowNetwork:Distribution:Component:Fan
 * This object defines the name of the supply Air Fan used in an Air loop.
 */
export interface AirflowNetwork_Distribution_Component_Fan {
  /**
   * Fan Name
   * Enter the name of the fan in the primary air loop.
   */
  fan_name: string;
  /**
   * Supply Fan Object Type
   * Default: "Fan:ConstantVolume"
   */
  supply_fan_object_type?:
    'Fan:ConstantVolume' | 'Fan:OnOff' | 'Fan:SystemModel' | 'Fan:VariableVolume';
}

/**
 * AirflowNetwork:Distribution:Component:Coil
 * This object defines the name of a coil used in an air loop.
 */
export interface AirflowNetwork_Distribution_Component_Coil {
  /**
   * Coil Name
   * Enter the name of a cooling or heating coil in the primary Air loop.
   */
  coil_name: string;
  /**
   * Coil Object Type
   * Select the type of coil corresponding to the name entered in the field above.
   */
  coil_object_type:
    | 'Coil:Cooling:DX'
    | 'Coil:Cooling:DX:MultiSpeed'
    | 'Coil:Cooling:DX:SingleSpeed'
    | 'Coil:Cooling:DX:TwoSpeed'
    | 'Coil:Cooling:DX:TwoStageWithHumidityControlMode'
    | 'Coil:Cooling:Water'
    | 'Coil:Cooling:Water:DetailedGeometry'
    | 'Coil:Heating:DX:MultiSpeed'
    | 'Coil:Heating:DX:SingleSpeed'
    | 'Coil:Heating:Desuperheater'
    | 'Coil:Heating:Electric'
    | 'Coil:Heating:Fuel'
    | 'Coil:Heating:Water';
  /**
   * Air Path Length
   * Enter the air path length (depth) for the coil.
   * Units: m
   */
  air_path_length: number;
  /**
   * Air Path Hydraulic Diameter
   * Enter the hydraulic diameter of this coil. The hydraulic diameter is defined as 4 multiplied by the cross section area divided by perimeter.
   * Units: m
   */
  air_path_hydraulic_diameter: number;
}

/**
 * AirflowNetwork:Distribution:Component:HeatExchanger
 * This object defines the name of an air-to-air heat exchanger used in an air loop.
 */
export interface AirflowNetwork_Distribution_Component_HeatExchanger {
  /**
   * HeatExchanger Name
   * Enter the name of an air-to-air heat exchanger in the primary Air loop.
   */
  heatexchanger_name: string;
  /**
   * HeatExchanger Object Type
   * Select the type of heat exchanger corresponding to the name entered in the field above.
   */
  heatexchanger_object_type:
    | 'HeatExchanger:AirToAir:FlatPlate'
    | 'HeatExchanger:AirToAir:SensibleAndLatent'
    | 'HeatExchanger:Desiccant:BalancedFlow';
  /**
   * Air Path Length
   * Enter the air path length (depth) for the heat exchanger.
   * Units: m
   */
  air_path_length: number;
  /**
   * Air Path Hydraulic Diameter
   * Enter the hydraulic diameter of this heat exchanger. The hydraulic diameter is defined as 4 multiplied by the cross section area divided by perimeter.
   * Units: m
   */
  air_path_hydraulic_diameter: number;
}

/**
 * AirflowNetwork:Distribution:Component:TerminalUnit
 * This object defines the name of a terminal unit in an air loop.
 */
export interface AirflowNetwork_Distribution_Component_TerminalUnit {
  /**
   * Terminal Unit Name
   * Enter the name of a terminal unit in the AirLoopHVAC.
   */
  terminal_unit_name: string;
  /**
   * Terminal Unit Object Type
   * Select the type of terminal unit corresponding to the name entered in the field above.
   */
  terminal_unit_object_type:
    'AirTerminal:SingleDuct:ConstantVolume:Reheat' | 'AirTerminal:SingleDuct:VAV:Reheat';
  /**
   * Air Path Length
   * Enter the air path length (depth) for the terminal unit.
   * Units: m
   */
  air_path_length: number;
  /**
   * Air Path Hydraulic Diameter
   * Enter the hydraulic diameter of this terminal unit. The hydraulic diameter is defined as 4 multiplied by the cross section area divided by perimeter.
   * Units: m
   */
  air_path_hydraulic_diameter: number;
}

/**
 * AirflowNetwork:Distribution:Component:ConstantPressureDrop
 * This object defines the characteristics of a constant pressure drop component (e.g. filter). Each node connected to this object can not be a node of mixer, splitter, a node of air primary loop, or zone equipment loop. It is recommended to connect to a duct component at both ends.
 */
export interface AirflowNetwork_Distribution_Component_ConstantPressureDrop {
  /**
   * Pressure Difference Across the Component
   * Enter the pressure drop across this component.
   * Units: Pa
   */
  pressure_difference_across_the_component: number;
}

/**
 * AirflowNetwork:Distribution:Component:OutdoorAirFlow
 * This object includes the outdoor air flow rate set by the Controller:OutdoorAir object in the airflow network.
 */
export interface AirflowNetwork_Distribution_Component_OutdoorAirFlow {
  /** Outdoor Air Mixer Name */
  outdoor_air_mixer_name: string;
  /**
   * Air Mass Flow Coefficient When No Outdoor Air Flow at Reference Conditions
   * Enter the air mass flow coefficient at the conditions defined in the Reference Crack Conditions object. Defined at 1 Pa pressure difference. Enter the coefficient used in the following equation: Mass Flow Rate = Air Mass Flow Coefficient * (dP)^Air Mass Flow Exponent. Used only when no outdoor air flow rate.
   * Units: kg/s
   */
  air_mass_flow_coefficient_when_no_outdoor_air_flow_at_reference_conditions: number;
  /**
   * Air Mass Flow Exponent When No Outdoor Air Flow
   * Enter the exponent used in the following equation: Mass Flow Rate = Air Mass Flow Coefficient * (dP)^Air Mass Flow Exponent. Used only when no outdoor air flow rate.
   * Units: dimensionless
   * Default: 0.65
   */
  air_mass_flow_exponent_when_no_outdoor_air_flow?: number;
  /**
   * Reference Crack Conditions
   * Select a AirflowNetwork:MultiZone:ReferenceCrackConditions name associated with the air mass flow coefficient entered above.
   */
  reference_crack_conditions?: string;
}

/**
 * AirflowNetwork:Distribution:Component:ReliefAirFlow
 * This object allows variation of air flow rate to perform pressure.
 */
export interface AirflowNetwork_Distribution_Component_ReliefAirFlow {
  /** Outdoor Air Mixer Name */
  outdoor_air_mixer_name: string;
  /**
   * Air Mass Flow Coefficient When No Outdoor Air Flow at Reference Conditions
   * Enter the air mass flow coefficient at the conditions defined in the Reference Crack Conditions object. Defined at 1 Pa pressure difference. Enter the coefficient used in the following equation: Mass Flow Rate = Air Mass Flow Coefficient * (dP)^Air Mass Flow Exponent. Used only when no outdoor air flow rate.
   * Units: kg/s
   */
  air_mass_flow_coefficient_when_no_outdoor_air_flow_at_reference_conditions: number;
  /**
   * Air Mass Flow Exponent When No Outdoor Air Flow
   * Enter the exponent used in the following equation: Mass Flow Rate = Air Mass Flow Coefficient * (dP)^Air Mass Flow Exponent. Used only when no outdoor air flow rate.
   * Units: dimensionless
   * Default: 0.65
   */
  air_mass_flow_exponent_when_no_outdoor_air_flow?: number;
  /**
   * Reference Crack Conditions
   * Select a AirflowNetwork:MultiZone:ReferenceCrackConditions name associated with the air mass flow coefficient entered above.
   */
  reference_crack_conditions?: string;
}

/**
 * AirflowNetwork:Distribution:Linkage
 * This object defines the connection between two nodes and a component.
 */
export interface AirflowNetwork_Distribution_Linkage {
  /**
   * Node 1 Name
   * Enter the name of zone or AirflowNetwork Node.
   */
  node_1_name: string;
  /**
   * Node 2 Name
   * Enter the name of zone or AirflowNetwork Node.
   */
  node_2_name: string;
  /**
   * Component Name
   * Enter the name of an AirflowNetwork component. A component is one of the following AirflowNetwork:Distribution:Component objects: Leak, LeakageRatio, Duct, ConstantVolumeFan, Coil, TerminalUnit, ConstantPressureDrop, or HeatExchanger.
   */
  component_name: string;
  /**
   * Thermal Zone Name
   * Only used if component = AirflowNetwork:Distribution:Component:Duct The zone name is where AirflowNetwork:Distribution:Component:Duct is exposed. Leave this field blank if the duct conduction loss is ignored.
   */
  thermal_zone_name?: string;
}

/**
 * AirflowNetwork:Distribution:DuctViewFactors
 * This object is used to allow user-defined view factors to be used for duct-surface radiation calculations.
 */
export interface AirflowNetwork_Distribution_DuctViewFactors {
  /** Linkage Name */
  linkage_name: string;
  /**
   * Duct Surface Exposure Fraction
   * Default: 0
   */
  duct_surface_exposure_fraction?: number;
  /**
   * Duct Surface Emittance
   * Default: 0.9
   */
  duct_surface_emittance?: number;
  /** Repeating group: surface_name, surface_view_factor */
  surfaces?: ExtensibleGroup[];
}

/**
 * AirflowNetwork:OccupantVentilationControl
 * This object is used to provide advanced thermal comfort control of window opening and closing for both exterior and interior windows.
 */
export interface AirflowNetwork_OccupantVentilationControl {
  /**
   * Minimum Opening Time
   * Units: minutes
   * Default: 0
   */
  minimum_opening_time?: number;
  /**
   * Minimum Closing Time
   * Units: minutes
   * Default: 0
   */
  minimum_closing_time?: number;
  /**
   * Thermal Comfort Low Temperature Curve Name
   * Enter a curve name that represents thermal comfort temperature as a function of outdoor dry-bulb temperature. Up to two curves are allowed if the performance cannot be represented by a single curve. The following two fields are used if two curves are required.
   */
  thermal_comfort_low_temperature_curve_name?: string;
  /**
   * Thermal Comfort Temperature Boundary Point
   * This point is used to allow separate low and high thermal comfort temperature curves. If a single performance curve is used, leave this field blank.
   * Units: C
   * Default: 10
   */
  thermal_comfort_temperature_boundary_point?: number;
  /**
   * Thermal Comfort High Temperature Curve Name
   * Enter a curve name that represents thermal comfort temperature as a function of outdoor dry-bulb temperature. Up to two curves are allowed if the performance cannot be represented by a single curve. If a single performance curve is used, leave this field blank.
   */
  thermal_comfort_high_temperature_curve_name?: string;
  /**
   * Maximum Threshold for Persons Dissatisfied PPD
   * Units: percent
   * Default: 10
   */
  maximum_threshold_for_persons_dissatisfied_ppd?: number;
  /**
   * Occupancy Check
   * If Yes, occupancy check will be performed as part of the opening probability check.
   * Default: "No"
   */
  occupancy_check?: 'No' | 'Yes';
  /**
   * Opening Probability Schedule Name
   * If this field is blank, the opening probability check is bypassed and opening is true.
   */
  opening_probability_schedule_name?: string;
  /**
   * Closing Probability Schedule Name
   * If this field is blank, the closing probability check is bypassed and closing is true.
   */
  closing_probability_schedule_name?: string;
}

