/**
 * HVACTemplate:Plant:Chiller
 * This object adds a chiller to an HVACTemplate:Plant:ChilledWaterLoop.
 */
export interface HVACTemplate_Plant_Chiller {
  /** Chiller Type */
  chiller_type:
    | 'DistrictChilledWater'
    | 'ElectricCentrifugalChiller'
    | 'ElectricReciprocatingChiller'
    | 'ElectricScrewChiller';
  /**
   * Capacity
   * Units: W
   * Default: "Autosize"
   */
  capacity?: number | 'Autosize' | 'Autocalculate';
  /**
   * Nominal COP
   * Not applicable if Chiller Type is DistrictChilledWater Electric Reciprocating Chiller
   * Units: W/W
   */
  nominal_cop: number;
  /**
   * Condenser Type
   * Not applicable if Chiller Type is DistrictChilledWater
   * Default: "WaterCooled"
   */
  condenser_type?: 'AirCooled' | 'EvaporativelyCooled' | 'WaterCooled';
  /**
   * Priority
   * If Chiller Plant Operation Scheme Type=Default in HVACTemplate:Plant:ChilledWaterLoop, then equipment operates in Priority order, 1, 2, 3, etc.
   */
  priority?: string;
  /**
   * Sizing Factor
   * Multiplies the autosized capacity and flow rates
   * Default: 1
   */
  sizing_factor?: number;
  /**
   * Minimum Part Load Ratio
   * Part load ratio below which the chiller starts cycling on/off to meet the load. Must be less than or equal to Maximum Part Load Ratio.
   * Default: 0
   */
  minimum_part_load_ratio?: number;
  /**
   * Maximum Part Load Ratio
   * Maximum allowable part load ratio. Must be greater than or equal to Minimum Part Load Ratio.
   * Default: 1
   */
  maximum_part_load_ratio?: number;
  /**
   * Optimum Part Load Ratio
   * Optimum part load ratio where the chiller is most efficient. Must be greater than or equal to the Minimum Part Load Ratio and less than or equal to the Maximum Part Load Ratio.
   * Default: 1
   */
  optimum_part_load_ratio?: number;
  /**
   * Minimum Unloading Ratio
   * Part load ratio where the chiller can no longer unload and false loading begins. Minimum unloading ratio must be greater than or equal to the Minimum Part Load Ratio and less than or equal to the Maximum Part Load Ratio.
   * Default: 0.25
   */
  minimum_unloading_ratio?: number;
  /**
   * Leaving Chilled Water Lower Temperature Limit
   * Units: C
   * Default: 5
   */
  leaving_chilled_water_lower_temperature_limit?: number;
}

