/**
 * Fan:ComponentModel
 * A detailed fan type for constant-air-volume (CAV) and variable-air-volume (VAV) systems. It includes inputs that describe the air-distribution system as well as the fan, drive belt (if used), motor, and variable-frequency-drive (if used).
 */
export interface Fan_ComponentModel {
  /** Air Inlet Node Name */
  air_inlet_node_name: string;
  /** Air Outlet Node Name */
  air_outlet_node_name: string;
  /**
   * Availability Schedule Name
   * Availability schedule name for this system. Schedule value > 0 means the system is available. If this field is blank, the system is always available.
   */
  availability_schedule_name?: string;
  /**
   * Maximum Flow Rate
   * Units: m3/s
   */
  maximum_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Minimum Flow Rate
   * Units: m3/s
   */
  minimum_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Fan Sizing Factor
   * Applied to specified or autosized max fan airflow
   * Default: 1
   */
  fan_sizing_factor?: number;
  /**
   * Fan Wheel Diameter
   * Diameter of wheel outer circumference
   * Units: m
   */
  fan_wheel_diameter: number;
  /**
   * Fan Outlet Area
   * Area at fan outlet plane for determining discharge velocity pressure
   * Units: m2
   */
  fan_outlet_area: number;
  /**
   * Maximum Fan Static Efficiency
   * Maximum ratio between power delivered to air and fan shaft input power Determined from fan performance data
   */
  maximum_fan_static_efficiency: number;
  /**
   * Euler Number at Maximum Fan Static Efficiency
   * Euler number (Eu) determined from fan performance data
   */
  euler_number_at_maximum_fan_static_efficiency: number;
  /**
   * Maximum Dimensionless Fan Airflow
   * Corresponds to maximum ratio between fan airflow and fan shaft rotational speed for specified fan wheel diameter Determined from fan performance data
   */
  maximum_dimensionless_fan_airflow: number;
  /**
   * Motor Fan Pulley Ratio
   * Ratio of motor pulley diameter to fan pulley diameter
   * Default: 1
   */
  motor_fan_pulley_ratio?: number | 'Autosize' | 'Autocalculate';
  /**
   * Belt Maximum Torque
   * Maximum torque transmitted by belt
   * Units: N-m
   */
  belt_maximum_torque: number | 'Autosize' | 'Autocalculate';
  /**
   * Belt Sizing Factor
   * Applied to specified or autosized max torque transmitted by belt
   * Default: 1
   */
  belt_sizing_factor?: number;
  /**
   * Belt Fractional Torque Transition
   * Region 1 to 2 curve transition for belt normalized efficiency
   * Default: 0.167
   */
  belt_fractional_torque_transition?: number;
  /**
   * Motor Maximum Speed
   * Maximum rotational speed of fan motor shaft
   * Units: rev/min
   */
  motor_maximum_speed: number;
  /**
   * Maximum Motor Output Power
   * Maximum power input to drive belt by motor
   * Units: W
   */
  maximum_motor_output_power: number | 'Autosize' | 'Autocalculate';
  /**
   * Motor Sizing Factor
   * Applied to specified or autosized motor output power
   * Default: 1
   */
  motor_sizing_factor?: number;
  /**
   * Motor In Airstream Fraction
   * 0.0 means motor outside air stream 1.0 means motor inside air stream
   * Default: 1
   */
  motor_in_airstream_fraction?: number;
  /**
   * VFD Efficiency Type
   * Efficiency depends on fraction of full-load motor speed Efficiency depends on  fraction of full-load motor input power If field blank, then assumes constant VFD efficiency (0.97)
   */
  vfd_efficiency_type?: 'Power' | 'Speed';
  /**
   * Maximum VFD Output Power
   * Maximum power input to motor by VFD
   * Units: W
   */
  maximum_vfd_output_power: number | 'Autosize' | 'Autocalculate';
  /**
   * VFD Sizing Factor
   * Applied to specified or autosized VFD output power
   * Default: 1
   */
  vfd_sizing_factor?: number;
  /**
   * Fan Pressure Rise Curve Name
   * Pressure rise depends on volumetric flow, system resistances, system leakage, and duct static pressure set point
   */
  fan_pressure_rise_curve_name: string;
  /**
   * Duct Static Pressure Reset Curve Name
   * Function of fan volumetric flow Minimum and maximum fan airflows correspond respectively to minimum and maximum duct static pressure set points
   */
  duct_static_pressure_reset_curve_name: string;
  /**
   * Normalized Fan Static Efficiency Curve Name-Non-Stall Region
   * xfan <= 0 Curve should have maximum of 1.0
   */
  normalized_fan_static_efficiency_curve_name_non_stall_region: string;
  /**
   * Normalized Fan Static Efficiency Curve Name-Stall Region
   * xfan > 0 Curve should have maximum of 1.0
   */
  normalized_fan_static_efficiency_curve_name_stall_region: string;
  /**
   * Normalized Dimensionless Airflow Curve Name-Non-Stall Region
   * xspd <= 0 Curve should have maximum of 1.0
   */
  normalized_dimensionless_airflow_curve_name_non_stall_region: string;
  /**
   * Normalized Dimensionless Airflow Curve Name-Stall Region
   * xspd > 0 Curve should have maximum of 1.0
   */
  normalized_dimensionless_airflow_curve_name_stall_region: string;
  /**
   * Maximum Belt Efficiency Curve Name
   * Determines maximum fan drive belt efficiency in log space as function of xbelt,max Curve should have minimum of -4.6 and maximum of 0.0 If field blank, assumes output of curve is always 1.0
   */
  maximum_belt_efficiency_curve_name?: string;
  /**
   * Normalized Belt Efficiency Curve Name - Region 1
   * Region 1 (0 <= xbelt < xbelt,trans) Curve should have minimum > 0.0 and maximum of 1.0 If field blank, assumes output of curve is always 1.0 in Region 1
   */
  normalized_belt_efficiency_curve_name_region_1?: string;
  /**
   * Normalized Belt Efficiency Curve Name - Region 2
   * Region 2 (xbelt,trans <= xbelt <= 1) Curve should have minimum > 0.0 and maximum of 1.0 If field blank, assumes output of curve is always 1.0 in Region 2
   */
  normalized_belt_efficiency_curve_name_region_2?: string;
  /**
   * Normalized Belt Efficiency Curve Name - Region 3
   * Determines normalized drive belt efficiency Region 3 (xbelt > 1) Curve should have minimum > 0.0 and maximum of 1.0 If field blank, assumes output of curve is always 1.0 in Region 3
   */
  normalized_belt_efficiency_curve_name_region_3?: string;
  /**
   * Maximum Motor Efficiency Curve Name
   * Curve should have minimum > 0.0 and maximum of 1.0 If field blank, assumes output of curve is always 1.0
   */
  maximum_motor_efficiency_curve_name?: string;
  /**
   * Normalized Motor Efficiency Curve Name
   * Curve should have minimum > 0.0 and maximum of 1.0 If field blank, assumes output of curve is always 1.0
   */
  normalized_motor_efficiency_curve_name?: string;
  /**
   * VFD Efficiency Curve Name
   * Determines VFD efficiency as function of motor load or speed fraction Curve should have minimum > 0.0 and maximum of 1.0 If field blank, assumes constant VFD efficiency (0.97)
   */
  vfd_efficiency_curve_name?: string;
  /**
   * End-Use Subcategory
   * Any text may be used here to categorize the end-uses in the ABUPS End Uses by Subcategory table.
   * Default: "General"
   */
  end_use_subcategory?: string;
}

/**
 * Coil:Cooling:Water
 * Chilled water cooling coil, NTU-effectiveness model, with inputs for design entering and leaving conditions.
 */
export interface Coil_Cooling_Water {
  /**
   * Availability Schedule Name
   * Availability schedule name for this system. Schedule value > 0 means the system is available. If this field is blank, the system is always available.
   */
  availability_schedule_name?: string;
  /**
   * Design Water Flow Rate
   * Units: m3/s
   * Default: "Autosize"
   */
  design_water_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Air Flow Rate
   * Units: m3/s
   * Default: "Autosize"
   */
  design_air_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Inlet Water Temperature
   * Units: C
   * Default: "Autosize"
   */
  design_inlet_water_temperature?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Inlet Air Temperature
   * Units: C
   * Default: "Autosize"
   */
  design_inlet_air_temperature?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Outlet Air Temperature
   * Units: C
   * Default: "Autosize"
   */
  design_outlet_air_temperature?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Inlet Air Humidity Ratio
   * Units: kgWater/kgDryAir
   * Default: "Autosize"
   */
  design_inlet_air_humidity_ratio?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Outlet Air Humidity Ratio
   * Units: kgWater/kgDryAir
   * Default: "Autosize"
   */
  design_outlet_air_humidity_ratio?: number | 'Autosize' | 'Autocalculate';
  /** Water Inlet Node Name */
  water_inlet_node_name: string;
  /** Water Outlet Node Name */
  water_outlet_node_name: string;
  /** Air Inlet Node Name */
  air_inlet_node_name: string;
  /** Air Outlet Node Name */
  air_outlet_node_name: string;
  /**
   * Type of Analysis
   * Default: "SimpleAnalysis"
   */
  type_of_analysis?: 'DetailedAnalysis' | 'SimpleAnalysis';
  /**
   * Heat Exchanger Configuration
   * Default: "CounterFlow"
   */
  heat_exchanger_configuration?: 'CounterFlow' | 'CrossFlow';
  /** Condensate Collection Water Storage Tank Name */
  condensate_collection_water_storage_tank_name?: string;
  /**
   * Design Water Temperature Difference
   * This input field is optional. If specified, it is used for sizing the Design Water Flow Rate. If blank or omitted, the Loop Design Temperature Difference value specified in Sizing:Plant object is used for sizing the Design Water Flow Rate.
   * Units: deltaC
   */
  design_water_temperature_difference?: number;
}

/**
 * Coil:Cooling:Water:DetailedGeometry
 * Chilled water cooling coil, detailed flat fin coil model for continuous plate fins, with inputs for detailed coil geometry specifications.
 */
export interface Coil_Cooling_Water_DetailedGeometry {
  /**
   * Availability Schedule Name
   * Availability schedule name for this system. Schedule value > 0 means the system is available. If this field is blank, the system is always available.
   */
  availability_schedule_name?: string;
  /**
   * Maximum Water Flow Rate
   * Units: m3/s
   * Default: "Autosize"
   */
  maximum_water_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Tube Outside Surface Area
   * Tube Primary Surface Area
   * Units: m2
   * Default: "Autosize"
   */
  tube_outside_surface_area?: number | 'Autosize' | 'Autocalculate';
  /**
   * Total Tube Inside Area
   * Total tube inside surface area
   * Units: m2
   * Default: "Autosize"
   */
  total_tube_inside_area?: number | 'Autosize' | 'Autocalculate';
  /**
   * Fin Surface Area
   * Units: m2
   * Default: "Autosize"
   */
  fin_surface_area?: number | 'Autosize' | 'Autocalculate';
  /**
   * Minimum Airflow Area
   * Units: m2
   * Default: "Autosize"
   */
  minimum_airflow_area?: number | 'Autosize' | 'Autocalculate';
  /**
   * Coil Depth
   * Units: m
   * Default: "Autosize"
   */
  coil_depth?: number | 'Autosize' | 'Autocalculate';
  /**
   * Fin Diameter
   * Fin diameter or the coil height
   * Units: m
   * Default: "Autosize"
   */
  fin_diameter?: number | 'Autosize' | 'Autocalculate';
  /**
   * Fin Thickness
   * Units: m
   * Default: 0.0015
   */
  fin_thickness?: number;
  /**
   * Tube Inside Diameter
   * Inner diameter of tubes
   * Units: m
   * Default: 0.01445
   */
  tube_inside_diameter?: number;
  /**
   * Tube Outside Diameter
   * Outer diameter of tubes
   * Units: m
   * Default: 0.0159
   */
  tube_outside_diameter?: number;
  /**
   * Tube Thermal Conductivity
   * Units: W/m-K
   * Default: 386
   */
  tube_thermal_conductivity?: number;
  /**
   * Fin Thermal Conductivity
   * Units: W/m-K
   * Default: 204
   */
  fin_thermal_conductivity?: number;
  /**
   * Fin Spacing
   * Fin spacing or distance
   * Units: m
   * Default: 0.0018
   */
  fin_spacing?: number;
  /**
   * Tube Depth Spacing
   * Units: m
   * Default: 0.026
   */
  tube_depth_spacing?: number;
  /**
   * Number of Tube Rows
   * Default: 4
   */
  number_of_tube_rows?: number;
  /**
   * Number of Tubes per Row
   * Default: "Autosize"
   */
  number_of_tubes_per_row?: number | 'Autosize' | 'Autocalculate';
  /** Water Inlet Node Name */
  water_inlet_node_name: string;
  /** Water Outlet Node Name */
  water_outlet_node_name: string;
  /** Air Inlet Node Name */
  air_inlet_node_name: string;
  /** Air Outlet Node Name */
  air_outlet_node_name: string;
  /** Condensate Collection Water Storage Tank Name */
  condensate_collection_water_storage_tank_name?: string;
  /**
   * Design Water Temperature Difference
   * This input field is optional. If specified, it is used for sizing the Design Water Flow Rate. If blank or omitted, the Loop Design Temperature Difference value specified in Sizing:Plant object is used for sizing the Design Water Flow Rate.
   * Units: deltaC
   */
  design_water_temperature_difference?: number;
}

/**
 * Coil:Cooling:DX
 * New general DX cooling coil supporting on or more speeds and one or or operating  modes. Includes DX evaporator coil, compressor, and condenser. Object is currently only supported by the AIRLOOPHVAC:UNITARYSYSTEM object. Remaining Coil:Cooling:DX* objects will be deprecated at a future date, after which, this object will replace all other Coil:Cooling:DX* objects.
 */
export interface Coil_Cooling_DX {
  /** Evaporator Inlet Node Name */
  evaporator_inlet_node_name: string;
  /** Evaporator Outlet Node Name */
  evaporator_outlet_node_name: string;
  /**
   * Availability Schedule Name
   * Schedule value > 0 means the coil is available. If this field is blank, the coil is always available.
   */
  availability_schedule_name?: string;
  /**
   * Condenser Zone Name
   * This input field is name of a conditioned or unconditioned zone where the secondary coil (condenser) of a DX system or heat pump is to be placed.  This is an optional input field specified only when the user desires to reject the condenser heat into a zone. The heat rejected is modeled as internal sensible heat gain of the zone.
   */
  condenser_zone_name?: string;
  /**
   * Condenser Inlet Node Name
   * This is the name of an air node in the simulation.  This may be an explicitly defined outdoor air node, or it may be a separate air node.
   */
  condenser_inlet_node_name: string;
  /**
   * Condenser Outlet Node Name
   * This is the name of an air node in the simulation.
   */
  condenser_outlet_node_name: string;
  /** Performance Object Name */
  performance_object_name: string;
  /** Condensate Collection Water Storage Tank Name */
  condensate_collection_water_storage_tank_name?: string;
  /** Evaporative Condenser Supply Water Storage Tank Name */
  evaporative_condenser_supply_water_storage_tank_name?: string;
}

/**
 * Coil:Cooling:DX:CurveFit:Performance
 * DX cooling coil performance specification referencing one or more operating modes. Mode 1 is always the base design operating mode. Additional modes are optional states such as subcool reheat for humidity control.
 */
export interface Coil_Cooling_DX_CurveFit_Performance {
  /**
   * Crankcase Heater Capacity
   * Units: W
   * Default: 0
   */
  crankcase_heater_capacity?: number;
  /**
   * Minimum Outdoor Dry-Bulb Temperature for Compressor Operation
   * Units: C
   * Default: -25
   */
  minimum_outdoor_dry_bulb_temperature_for_compressor_operation?: number;
  /**
   * Maximum Outdoor Dry-Bulb Temperature for Crankcase Heater Operation
   * Units: C
   * Default: 10
   */
  maximum_outdoor_dry_bulb_temperature_for_crankcase_heater_operation?: number;
  /**
   * Unit Internal Static Air Pressure
   * Enter pressure drop for the unit containing the coil. This value is only used to calculate Energy Efficiency Ratio (EER), Integrated Energy Efficiency Ratio (IEER), and the Standard Rating (Net) Cooling Capacity. This value is not used for modeling the evaporator fan during simulations.
   * Units: Pa
   */
  unit_internal_static_air_pressure?: number;
  /**
   * Capacity Control Method
   * Default: "Discrete"
   */
  capacity_control_method?: 'Continuous' | 'Discrete';
  /**
   * Evaporative Condenser Basin Heater Capacity
   * This field is only used for Condenser Type = EvaporativelyCooled and for periods when the basin heater is available (field Basin Heater Operating Schedule Name). For this situation, the heater maintains the basin water temperature at the basin heater setpoint temperature when the outdoor air temperature falls below the setpoint temperature. The basin heater only operates when the DX coil is off.
   * Units: W/K
   * Default: 0
   */
  evaporative_condenser_basin_heater_capacity?: number;
  /**
   * Evaporative Condenser Basin Heater Setpoint Temperature
   * This field is only used for Condenser Type = EvaporativelyCooled. Enter the outdoor dry-bulb temperature when the basin heater turns on.
   * Units: C
   * Default: 2
   */
  evaporative_condenser_basin_heater_setpoint_temperature?: number;
  /**
   * Evaporative Condenser Basin Heater Operating Schedule Name
   * This field is only used for Condenser Type = EvaporativelyCooled. Schedule values greater than 0 allow the basin heater to operate whenever the outdoor air dry-bulb temperature is below the basin heater setpoint temperature. If a schedule name is not entered, the basin heater is allowed to operate throughout the entire simulation.
   */
  evaporative_condenser_basin_heater_operating_schedule_name?: string;
  /**
   * Compressor Fuel Type
   * Default: "Electricity"
   */
  compressor_fuel_type?:
    | 'Diesel'
    | 'Electricity'
    | 'FuelOilNo1'
    | 'FuelOilNo2'
    | 'Gasoline'
    | 'NaturalGas'
    | 'OtherFuel1'
    | 'OtherFuel2'
    | 'Propane';
  /**
   * Base Operating Mode
   * Operating Mode 1 is always used as the base design operating mode.
   */
  base_operating_mode: string;
  /**
   * Alternative Operating Mode 1
   * The alternative operating mode is used for enhanced dehumidification. If this is blank, the coil will always operate in the base operating mode. If an alternate mode is defined here, the coil will use the enhanced mode if activated by the parent system controls.
   */
  alternative_operating_mode_1?: string;
  /**
   * Alternative Operating Mode 2
   * The alternative operating mode is used for enhanced dehumidification. If this is blank, the coil will always operate in the base operating mode or Alternative Mode 1. If both Alternative Operating Mode 1 and Mode 2 are defined here, the coil will perform both Subcool and Reheat modes for enhanced dehumidification. Alternative Operating Mode 1 is used as Subcool mode, and Alternative Operating Mode 2 is used as Reheat mode.
   */
  alternative_operating_mode_2?: string;
}

/**
 * Coil:Cooling:DX:CurveFit:OperatingMode
 * DX cooling coil performance for a single operating mode which may have one or more speeds.
 */
export interface Coil_Cooling_DX_CurveFit_OperatingMode {
  /**
   * Rated Gross Total Cooling Capacity
   * Total (sensible+latent) cooling capacity not accounting for the effect of supply air fan heat. Rating point: air entering the evaporator coil at 26.7 C dry-bulb/19.4 C wet-bulb, and air entering the condenser coil at 35 C dry-bulb/23.9 C wet-bulb. gross capacity excluding supply air fan heat
   * Units: W
   * Default: "Autosize"
   */
  rated_gross_total_cooling_capacity?: number | 'Autosize' | 'Autocalculate';
  /**
   * Rated Evaporator Air Flow Rate
   * Flow rate corresponding to rated total cooling capacity, Rated SHR and Rated COP. Should be between 0.00004027 m3/s and 0.00006041 m3/s per watt of rated total cooling capacity.
   * Units: m3/s
   */
  rated_evaporator_air_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Rated Condenser Air Flow Rate
   * Used to calculate evaporative condenser water use.
   * Units: m3/s
   */
  rated_condenser_air_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Maximum Cycling Rate
   * The maximum on-off cycling Rate for the compressor, which occurs at 50% run time fraction. Suggested value is 3; zero value means latent degradation model is disabled.
   * Units: cycles/hr
   * Default: 0
   */
  maximum_cycling_rate?: number;
  /**
   * Ratio of Initial Moisture Evaporation Rate and Steady State Latent Capacity
   * Ratio of the initial moisture evaporation rate from the cooling coil (when the compressor first turns off) and the coil's steady state latent capacity at rated air flow rate and temperature conditions. Suggested value is 1.5; zero value means latent degradation model is disabled.
   * Units: dimensionless
   * Default: 0
   */
  ratio_of_initial_moisture_evaporation_rate_and_steady_state_latent_capacity?: number;
  /**
   * Latent Capacity Time Constant
   * Time constant for the cooling coil's latent capacity to reach steady state after startup. Suggested value is 45; zero value means latent degradation model is disabled.
   * Units: s
   * Default: 0
   */
  latent_capacity_time_constant?: number;
  /**
   * Nominal Time for Condensate Removal to Begin
   * The nominal time for condensate to begin leaving the coil's condensate drain line at the coil's rated air flow rate and temperature conditions. Nominal time is equal to the ratio of the energy of the coil's maximum condensate holding capacity (J) to the coil's steady state latent capacity (W). Suggested value is 1000; zero value means latent degradation model is disabled.
   * Units: s
   * Default: 0
   */
  nominal_time_for_condensate_removal_to_begin?: number;
  /**
   * Apply Latent Degradation to Speeds Greater than 1
   * Default: "No"
   */
  apply_latent_degradation_to_speeds_greater_than_1?: 'No' | 'Yes';
  /**
   * Condenser Type
   * Default: "AirCooled"
   */
  condenser_type?: 'AirCooled' | 'EvaporativelyCooled';
  /**
   * Nominal Evaporative Condenser Pump Power
   * Rated power consumed by the evaporative condenser's water pump
   * Units: W
   * Default: 0
   */
  nominal_evaporative_condenser_pump_power?: number | 'Autosize' | 'Autocalculate';
  /**
   * Nominal Speed Number
   * Must be lower than or equal to the highest speed number. If blank, defaults to the highest speed number used.
   */
  nominal_speed_number?: number;
  /** Speed 1 Name */
  speed_1_name: string;
  /** Speed 2 Name */
  speed_2_name?: string;
  /** Speed 3 Name */
  speed_3_name?: string;
  /** Speed 4 Name */
  speed_4_name?: string;
  /** Speed 5 Name */
  speed_5_name?: string;
  /** Speed 6 Name */
  speed_6_name?: string;
  /** Speed 7 Name */
  speed_7_name?: string;
  /** Speed 8 Name */
  speed_8_name?: string;
  /** Speed 9 Name */
  speed_9_name?: string;
  /** Speed 10 Name */
  speed_10_name?: string;
}

/**
 * Coil:Cooling:DX:CurveFit:Speed
 * DX cooling coil performance for a single speed within a single operating mode.
 */
export interface Coil_Cooling_DX_CurveFit_Speed {
  /**
   * Gross Total Cooling Capacity Fraction
   * Ratio of capacity at this speed to the operating mode Rated Gross Total Cooling Capacity
   */
  gross_total_cooling_capacity_fraction: number;
  /**
   * Evaporator Air Flow Rate Fraction
   * Ratio of capacity at this speed to the operating mode Rated Evaporator Air Flow Rate
   */
  evaporator_air_flow_rate_fraction: number;
  /**
   * Condenser Air Flow Rate Fraction
   * Ratio of condenser air flow at this speed to the operating mode Rated Condenser Air Flow Rate
   */
  condenser_air_flow_rate_fraction?: number;
  /**
   * Gross Sensible Heat Ratio
   * Rated sensible heat ratio (gross sensible capacity/gross total capacity) sensible and total capacities do not include supply fan heat
   * Default: "Autosize"
   */
  gross_sensible_heat_ratio?: number | 'Autosize' | 'Autocalculate';
  /**
   * Gross Cooling COP
   * Gross cooling capacity divided by power input to the compressor and condenser fan. Does not include supply fan heat or supply fan electrical energy input.
   * Units: W/W
   * Default: 3
   */
  gross_cooling_cop?: number;
  /**
   * Active Fraction of Coil Face Area
   * The fraction of the cooling coil face which is actively cooled at this speed. For non-split-face coils, this should be 1.0.
   * Default: 1
   */
  active_fraction_of_coil_face_area?: number;
  /**
   * Rated Evaporator Fan Power Per Volume Flow Rate
   * Enter the evaporator fan power per air volume flow rate at the rated test conditions. The test conditions vary external static pressure based on total cooling capacity. This value is only used to calculate Seasonal Energy Efficiency Ratio (SEER), and the Standard Rating (Net) Cooling Capacity which will be outputs in the EnergyPlus eio file. This value is not used for modeling the evaporator fan during simulations.
   * Units: W/(m3/s)
   * Default: 773.3
   */
  rated_evaporator_fan_power_per_volume_flow_rate?: number;
  /**
   * Evaporative Condenser Pump Power Fraction
   * Ratio of evaporative condenser pump power at this speed to the operating mode Nominal Evaporative Condenser Pump Power
   * Default: 1
   */
  evaporative_condenser_pump_power_fraction?: number;
  /**
   * Evaporative Condenser Effectiveness
   * Units: dimensionless
   * Default: 0.9
   */
  evaporative_condenser_effectiveness?: number;
  /**
   * Total Cooling Capacity Modifier Function of Temperature Curve Name
   * biquadratic curve = a + b*wb + c*wb**2 + d*edb + e*edb**2 + f*wb*edb quadratic curve = a + b*edb + c*edb**2 wb = entering wet-bulb temperature (C) edb = dry-bulb temperature seen by the condenser (C)
   */
  total_cooling_capacity_modifier_function_of_temperature_curve_name?: string;
  /**
   * Total Cooling Capacity Modifier Function of Air Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = Fraction of the full load flow
   */
  total_cooling_capacity_modifier_function_of_air_flow_fraction_curve_name?: string;
  /**
   * Energy Input Ratio Modifier Function of Temperature Curve Name
   * curve = a + b*wb + c*wb**2 + d*edb + e*edb**2 + f*wb*edb wb = entering wet-bulb temperature (C) edb = dry-bulb temperature seen by the condenser (C)
   */
  energy_input_ratio_modifier_function_of_temperature_curve_name?: string;
  /**
   * Energy Input Ratio Modifier Function of Air Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = Fraction of the full load flow
   */
  energy_input_ratio_modifier_function_of_air_flow_fraction_curve_name?: string;
  /**
   * Part Load Fraction Correlation Curve Name
   * quadratic curve = a + b*PLR + c*PLR**2 cubic curve = a + b*PLR + c*PLR**2 + d*PLR**3 PLR = part load ratio (cooling load/steady state capacity)
   */
  part_load_fraction_correlation_curve_name?: string;
  /**
   * Rated Waste Heat Fraction of Power Input
   * Recoverable waste heat at full load and rated conditions
   * Units: dimensionless
   * Default: 0.2
   */
  rated_waste_heat_fraction_of_power_input?: number;
  /**
   * Waste Heat Modifier Function of Temperature Curve Name
   * curve = a + b*cdb + c*cdb**2 + d*edb + e*edb**2 + f*cdb*edb cdb = entering condenser dry-bulb temperature (C) edb = entering coil dry-bulb temperature (C)
   */
  waste_heat_modifier_function_of_temperature_curve_name?: string;
  /**
   * Sensible Heat Ratio Modifier Function of Temperature Curve Name
   * curve = a + b*wb + c*wb**2 + d*db + e*db**2 + f*wb*db wb = entering wet-bulb temperature seen by the DX cooling coil (C) db = entering dry-bulb temperature seen by the DX cooling coil (C) entering temperature can be outside air or pretreated air. If this curve is used and the Sensible Heat Ratio Modifier Function of Flow Fraction (SHRFFF) Curve Name is blank, the SHRFFF is assumed to be a constant value of 1.0.
   */
  sensible_heat_ratio_modifier_function_of_temperature_curve_name?: string;
  /**
   * Sensible Heat Ratio Modifier Function of Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = fraction of the full load flow If this curve is used and the Sensible Heat Ratio Modifier Function of Temperature Curve Name (SHRFT) Curve Name is blank, the SHRFT is assumed to be a constant value of 1.0.
   */
  sensible_heat_ratio_modifier_function_of_flow_fraction_curve_name?: string;
}

/**
 * Coil:Cooling:DX:SingleSpeed
 * Direct expansion (DX) cooling coil and condensing unit (includes electric compressor and condenser fan), single-speed. Optional inputs for moisture evaporation from wet coil when compressor cycles off with continuous fan operation.
 */
export interface Coil_Cooling_DX_SingleSpeed {
  /**
   * Availability Schedule Name
   * Availability schedule name for this system. Schedule value > 0 means the system is available. If this field is blank, the system is always available.
   */
  availability_schedule_name?: string;
  /**
   * Gross Rated Total Cooling Capacity
   * Total cooling capacity not accounting for the effect of supply air fan heat gross capacity excluding supply air fan heat rating point: air entering the cooling coil at 26.7 C dry-bulb/19.4 C wet-bulb, and air entering the outdoor condenser coil at 35 C dry-bulb/23.9 C wet-bulb
   * Units: W
   */
  gross_rated_total_cooling_capacity: number | 'Autosize' | 'Autocalculate';
  /**
   * Gross Rated Sensible Heat Ratio
   * Rated sensible heat ratio (gross sensible capacity/gross total capacity) sensible and total capacities do not include supply fan heat
   */
  gross_rated_sensible_heat_ratio: number | 'Autosize' | 'Autocalculate';
  /**
   * Gross Rated Cooling COP
   * Gross cooling capacity divided by power input to the compressor and outdoor fan, does not include supply fan heat or supply fan electrical energy input
   * Units: W/W
   * Default: 3
   */
  gross_rated_cooling_cop?: number;
  /**
   * Rated Air Flow Rate
   * Flow rate corresponding to rated total cooling capacity, Rated SHR and Rated COP should be between 0.00004027 m3/s and .00006041 m3/s per watt of rated total cooling capacity
   * Units: m3/s
   */
  rated_air_flow_rate: number | 'Autosize' | 'Autocalculate';
  /**
   * Rated Evaporator Fan Power Per Volume Flow Rate
   * Enter the evaporator fan power per air volume flow rate at the rated test conditions. The test conditions vary external static pressure based on total cooling capacity. This value is only used to calculate Seasonal Energy Efficiency Ratio (SEER), Energy Efficiency Ratio (EER), Integrated Energy Efficiency Ratio (IEER), and the Standard Rating (Net) Cooling Capacity which will be outputs in the EnergyPlus eio file.  This value is not used for modeling the evaporator fan during simulations.
   * Units: W/(m3/s)
   * Default: 773.3
   */
  rated_evaporator_fan_power_per_volume_flow_rate?: number;
  /** Air Inlet Node Name */
  air_inlet_node_name: string;
  /** Air Outlet Node Name */
  air_outlet_node_name: string;
  /**
   * Total Cooling Capacity Function of Temperature Curve Name
   * curve = a + b*wb + c*wb**2 + d*edb + e*edb**2 + f*wb*edb wb = entering wet-bulb temperature (C) edb = dry-bulb temperature seen by the condenser (C)
   */
  total_cooling_capacity_function_of_temperature_curve_name: string;
  /**
   * Total Cooling Capacity Function of Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = Fraction of the full load flow
   */
  total_cooling_capacity_function_of_flow_fraction_curve_name: string;
  /**
   * Energy Input Ratio Function of Temperature Curve Name
   * curve = a + b*wb + c*wb**2 + d*edb + e*edb**2 + f*wb*edb wb = entering wet-bulb temperature (C) edb = dry-bulb temperature seen by the condenser (C)
   */
  energy_input_ratio_function_of_temperature_curve_name: string;
  /**
   * Energy Input Ratio Function of Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = Fraction of the full load flow
   */
  energy_input_ratio_function_of_flow_fraction_curve_name: string;
  /**
   * Part Load Fraction Correlation Curve Name
   * quadratic curve = a + b*PLR + c*PLR**2 cubic curve = a + b*PLR + c*PLR**2 + d*PLR**3 PLR = part load ratio (cooling load/steady state capacity)
   */
  part_load_fraction_correlation_curve_name: string;
  /**
   * Minimum Outdoor Dry-Bulb Temperature for Compressor Operation
   * Units: C
   * Default: -25
   */
  minimum_outdoor_dry_bulb_temperature_for_compressor_operation?: number;
  /**
   * Nominal Time for Condensate Removal to Begin
   * The nominal time for condensate to begin leaving the coil's condensate drain line at the coil's rated air flow rate and temperature conditions. Nominal time is equal to the ratio of the energy of the coil's maximum condensate holding capacity (J) to the coil's steady state latent capacity (W). Suggested value is 1000; zero value means latent degradation model is disabled.
   * Units: s
   * Default: 0
   */
  nominal_time_for_condensate_removal_to_begin?: number;
  /**
   * Ratio of Initial Moisture Evaporation Rate and Steady State Latent Capacity
   * Ratio of the initial moisture evaporation rate from the cooling coil (when the compressor first turns off) and the coil's steady state latent capacity at rated air flow rate and temperature conditions. Suggested value is 1.5; zero value means latent degradation model is disabled.
   * Units: dimensionless
   * Default: 0
   */
  ratio_of_initial_moisture_evaporation_rate_and_steady_state_latent_capacity?: number;
  /**
   * Maximum Cycling Rate
   * The maximum on-off cycling Rate for the compressor, which occurs at 50% run time fraction. Suggested value is 3; zero value means latent degradation model is disabled.
   * Units: cycles/hr
   * Default: 0
   */
  maximum_cycling_rate?: number;
  /**
   * Latent Capacity Time Constant
   * Time constant for the cooling coil's latent capacity to reach steady state after startup. Suggested value is 45; zero value means latent degradation model is disabled.
   * Units: s
   * Default: 0
   */
  latent_capacity_time_constant?: number;
  /**
   * Condenser Air Inlet Node Name
   * Enter the name of an outdoor air node. This node name is also specified in an OutdoorAir:Node or OutdoorAir:NodeList object.
   */
  condenser_air_inlet_node_name?: string;
  /**
   * Condenser Type
   * Default: "AirCooled"
   */
  condenser_type?: 'AirCooled' | 'EvaporativelyCooled';
  /**
   * Evaporative Condenser Effectiveness
   * Units: dimensionless
   * Default: 0.9
   */
  evaporative_condenser_effectiveness?: number;
  /**
   * Evaporative Condenser Air Flow Rate
   * Used to calculate evaporative condenser water use
   * Units: m3/s
   */
  evaporative_condenser_air_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Evaporative Condenser Pump Rated Power Consumption
   * Rated power consumed by the evaporative condenser's water pump
   * Units: W
   * Default: 0
   */
  evaporative_condenser_pump_rated_power_consumption?: number | 'Autosize' | 'Autocalculate';
  /**
   * Crankcase Heater Capacity
   * Units: W
   * Default: 0
   */
  crankcase_heater_capacity?: number;
  /**
   * Maximum Outdoor Dry-Bulb Temperature for Crankcase Heater Operation
   * Units: C
   * Default: 10
   */
  maximum_outdoor_dry_bulb_temperature_for_crankcase_heater_operation?: number;
  /** Supply Water Storage Tank Name */
  supply_water_storage_tank_name?: string;
  /** Condensate Collection Water Storage Tank Name */
  condensate_collection_water_storage_tank_name?: string;
  /**
   * Basin Heater Capacity
   * This field is only used for Condenser Type = EvaporativelyCooled and for periods when the basin heater is available (field Basin Heater Operating Schedule Name). For this situation, the heater maintains the basin water temperature at the basin heater setpoint temperature when the outdoor air temperature falls below the setpoint temperature. The basin heater only operates when the DX coil is off.
   * Units: W/K
   * Default: 0
   */
  basin_heater_capacity?: number;
  /**
   * Basin Heater Setpoint Temperature
   * This field is only used for Condenser Type = EvaporativelyCooled. Enter the outdoor dry-bulb temperature when the basin heater turns on.
   * Units: C
   * Default: 2
   */
  basin_heater_setpoint_temperature?: number;
  /**
   * Basin Heater Operating Schedule Name
   * This field is only used for Condenser Type = EvaporativelyCooled. Schedule values greater than 0 allow the basin heater to operate whenever the outdoor air dry-bulb temperature is below the basin heater setpoint temperature. If a schedule name is not entered, the basin heater is allowed to operate throughout the entire simulation.
   */
  basin_heater_operating_schedule_name?: string;
  /**
   * Sensible Heat Ratio Function of Temperature Curve Name
   * curve = a + b*wb + c*wb**2 + d*db + e*db**2 + f*wb*db wb = entering wet-bulb temperature seen by the DX cooling coil (C) db = entering dry-bulb temperature seen by the DX cooling coil (C) entering temperature can be outside air or pretreated air.
   */
  sensible_heat_ratio_function_of_temperature_curve_name?: string;
  /**
   * Sensible Heat Ratio Function of Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = fraction of the full load flow
   */
  sensible_heat_ratio_function_of_flow_fraction_curve_name?: string;
  /**
   * Report ASHRAE Standard 127 Performance Ratings
   * when this input field is specified as Yes then the program calculates the net cooling capacity and total electric power input of DX cooling coils per ANSI/ASHRAE 127.
   * Default: "No"
   */
  report_ashrae_standard_127_performance_ratings?: 'No' | 'Yes';
  /**
   * Zone Name for Condenser Placement
   * This input field is name of a conditioned or unconditioned zone where the secondary coil (condenser) of DX system or a heat pump is to be placed.  This is an optional input field specified only when user desires to reject the condenser heat into a zone. The heat rejected is modelled as internal sensible heat gain of the zone.
   */
  zone_name_for_condenser_placement?: string;
}

