  /** Normal Mode Stage 1 Coil Performance Object Type */
  normal_mode_stage_1_coil_performance_object_type: 'CoilPerformance:DX:Cooling';
  /** Normal Mode Stage 1 Coil Performance Name */
  normal_mode_stage_1_coil_performance_name: string;
  /** Normal Mode Stage 1+2 Coil Performance Object Type */
  normal_mode_stage_1_2_coil_performance_object_type?: 'CoilPerformance:DX:Cooling';
  /** Normal Mode Stage 1+2 Coil Performance Name */
  normal_mode_stage_1_2_coil_performance_name?: string;
  /** Dehumidification Mode 1 Stage 1 Coil Performance Object Type */
  dehumidification_mode_1_stage_1_coil_performance_object_type?: 'CoilPerformance:DX:Cooling';
  /** Dehumidification Mode 1 Stage 1 Coil Performance Name */
  dehumidification_mode_1_stage_1_coil_performance_name?: string;
  /** Dehumidification Mode 1 Stage 1+2 Coil Performance Object Type */
  dehumidification_mode_1_stage_1_2_coil_performance_object_type?: 'CoilPerformance:DX:Cooling';
  /** Dehumidification Mode 1 Stage 1+2 Coil Performance Name */
  dehumidification_mode_1_stage_1_2_coil_performance_name?: string;
  /** Supply Water Storage Tank Name */
  supply_water_storage_tank_name?: string;
  /** Condensate Collection Water Storage Tank Name */
  condensate_collection_water_storage_tank_name?: string;
