/**
 * Coil:Heating:DX:SingleSpeed
 * Direct expansion (DX) heating coil (air-to-air heat pump) and compressor unit (includes electric compressor and outdoor fan), single-speed, with defrost controls.
 */
export interface Coil_Heating_DX_SingleSpeed {
  /**
   * Availability Schedule Name
   * Availability schedule name for this system. Schedule value > 0 means the system is available. If this field is blank, the system is always available.
   */
  availability_schedule_name?: string;
  /**
   * Gross Rated Heating Capacity
   * Heating capacity not accounting for the effect of supply air fan heat capacity excluding supply air fan heat rating point outdoor dry-bulb temp 8.33 C, outdoor wet-bulb temp 6.11 C rating point heating coil entering air dry-bulb 21.11 C, coil entering wet-bulb 15.55 C
   * Units: W
   */
  gross_rated_heating_capacity: number | 'Autosize' | 'Autocalculate';
  /**
   * Gross Rated Heating COP
   * Rated heating capacity divided by power input to the compressor and outdoor fan, does not include supply air fan heat or supply air fan electrical energy does not include supply air fan heat or supply air fan electrical energy
   * Units: W/W
   */
  gross_rated_heating_cop: number;
  /**
   * Rated Air Flow Rate
   * Flow rate corresponding to rated total capacity should be between 0.00004027 m3/s and .00006041 m3/s per watt of rated heating capacity
   * Units: m3/s
   */
  rated_air_flow_rate: number | 'Autosize' | 'Autocalculate';
  /**
   * Rated Supply Fan Power Per Volume Flow Rate
   * Enter the supply fan power per air volume flow rate at the rated test conditions. The test conditions vary external static pressure based on heating capacity. This value is only used to calculate Heating Seasonal Performance Factor(HSPF). This value is not used for modeling the supply (condenser) fan during simulations.
   * Units: W/(m3/s)
   * Default: 773.3
   */
  rated_supply_fan_power_per_volume_flow_rate?: number;
  /** Air Inlet Node Name */
  air_inlet_node_name: string;
  /** Air Outlet Node Name */
  air_outlet_node_name: string;
  /**
   * Heating Capacity Function of Temperature Curve Name
   * quadratic curve = a + b*oat + c*oat**2 cubic curve = a + b*oat + c*oat**2 + d*oat**3 biquadratic curve = a + b*iat + c*iat**2 + d*oat + e*oat**2 + f*iat*oat oat = outdoor air dry-bulb temperature (C) iat = indoor air dry-bulb temperature (C) Biquadratic curve is recommended if sufficient manufacturer data is available for the heating capacity to be sensitive to both iat and oat.
   */
  heating_capacity_function_of_temperature_curve_name: string;
  /**
   * Heating Capacity Function of Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = fraction of the full load flow
   */
  heating_capacity_function_of_flow_fraction_curve_name: string;
  /**
   * Energy Input Ratio Function of Temperature Curve Name
   * quadratic curve = a + b*oat + c*oat**2 cubic curve = a + b*oat + c*oat**2 + d*oat**3 biquadratic curve = a + b*iat + c*iat**2 + d*oat + e*oat**2 + f*iat*oat oat = outdoor air dry-bulb temperature (C) iat = indoor air dry-bulb temperature (C) biquadratic curve is recommended if sufficient manufacturer data is available for the energy input ratio to be sensitive to both iat and oat.
   */
  energy_input_ratio_function_of_temperature_curve_name: string;
  /**
   * Energy Input Ratio Function of Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = fraction of the full load flow
   */
  energy_input_ratio_function_of_flow_fraction_curve_name: string;
  /**
   * Part Load Fraction Correlation Curve Name
   * quadratic curve = a + b*PLR + c*PLR**2 cubic curve = a + b*PLR + c*PLR**2 + d*PLR**3 PLR = part load ratio (sensible heating load/steady state heating capacity)
   */
  part_load_fraction_correlation_curve_name: string;
  /**
   * Defrost Energy Input Ratio Function of Temperature Curve Name
   * biquadratic curve = a + b*wb + c*wb**2 + d*oat + e*oat**2 + f*wb*oat wb = wet-bulb temperature (C) of air entering the indoor coil oat = outdoor air dry-bulb temperature (C) only required if ReverseCycle defrost strategy is specified
   */
  defrost_energy_input_ratio_function_of_temperature_curve_name?: string;
  /**
   * Minimum Outdoor Dry-Bulb Temperature for Compressor Operation
   * Units: C
   * Default: -8
   */
  minimum_outdoor_dry_bulb_temperature_for_compressor_operation?: number;
  /**
   * Outdoor Dry-Bulb Temperature to Turn On Compressor
   * The outdoor temperature when the compressor is automatically turned back on following an automatic shut off because of low outdoor dry-bulb temperature. This field is only used for the calculation of HSPF. If this field is not provided, then outdoor bin temperature used in the HSPF calculation is always considered to be greater than this temperature and 'Minimum Outdoor Dry-Bulb Temperature for Compressor Operation' field described above. This assumption is based on AHRI standard 210/240 (2008) and can introduce significant error in the final value of HSPF.
   * Units: C
   */
  outdoor_dry_bulb_temperature_to_turn_on_compressor?: number;
  /**
   * Maximum Outdoor Dry-Bulb Temperature for Defrost Operation
   * Units: C
   * Default: 5
   */
  maximum_outdoor_dry_bulb_temperature_for_defrost_operation?: number;
  /**
   * Crankcase Heater Capacity
   * Units: W
   * Default: 0
   */
  crankcase_heater_capacity?: number;
  /**
   * Maximum Outdoor Dry-Bulb Temperature for Crankcase Heater Operation
   * Units: C
   * Default: 10
   */
  maximum_outdoor_dry_bulb_temperature_for_crankcase_heater_operation?: number;
  /**
   * Defrost Strategy
   * Default: "ReverseCycle"
   */
  defrost_strategy?: 'Resistive' | 'ReverseCycle';
  /**
   * Defrost Control
   * Default: "Timed"
   */
  defrost_control?: 'OnDemand' | 'Timed';
  /**
   * Defrost Time Period Fraction
   * Fraction of time in defrost mode only applicable if timed defrost control is specified
   * Default: 0.058333
   */
  defrost_time_period_fraction?: number;
  /**
   * Resistive Defrost Heater Capacity
   * only applicable if resistive defrost strategy is specified
   * Units: W
   * Default: 0
   */
  resistive_defrost_heater_capacity?: number | 'Autosize' | 'Autocalculate';
  /**
   * Region number for calculating HSPF
   * Standard Region number for which HSPF and other standard ratings are calculated
   * Default: 4
   */
  region_number_for_calculating_hspf?: number;
  /**
   * Evaporator Air Inlet Node Name
   * Enter the name of an outdoor air node. This node name is also specified in an OutdoorAir:Node or OutdoorAir:NodeList object.
   */
  evaporator_air_inlet_node_name?: string;
  /**
   * Zone Name for Evaporator Placement
   * This input field is name of a conditioned or unconditioned zone where the secondary coil (evaporator) of a heat pump is to be placed.  This is an optional input field specified only when user desires to extract heat from the zone.  The heat extracted is modelled as internal gain of the zone. If the primary DX system is a heat pump, then the zone name should be the same as the zone name specified for placing the secondary cooling DX coil.
   */
  zone_name_for_evaporator_placement?: string;
  /**
   * Secondary Coil Air Flow Rate
   * This input value is the secondary coil (evaporator) air flow rate when the heat pump is working in heating mode or the secondary DX coil (condenser) air flow rate when the heat pump is working in cooling mode.
   * Units: m3/s
   */
  secondary_coil_air_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Secondary Coil Fan Flow Scaling Factor
   * This input field is scaling factor for autosizing the secondary DX coil fan flow rate. The secondary air flow rate is determined by multiplying the primary DX coil rated air flow rate by the fan flow scaling factor. Default value is 1.25. If the secondary coil fan flow rate is not autosized, then the secondary coil fan flow scaling factor is set to 1.0.
   * Units: m3/s
   * Default: 1.25
   */
  secondary_coil_fan_flow_scaling_factor?: number;
  /**
   * Nominal Sensible Heat Ratio of Secondary Coil
   * This input value is the nominal sensible heat ratio used to split the heat extracted by a secondary DX coil (evaporator) of a heat pump into sensible and latent components. This is an optional input field.  If this input field is left blank, then pure sensible internal heat gain is assumed, i.e., sensible heat ratio of 1.0.
   * Units: m3/s
   */
  nominal_sensible_heat_ratio_of_secondary_coil?: number;
  /**
   * Sensible Heat Ratio Modifier Function of Temperature Curve Name
   * curve = a + b*wb + c*wb**2 + d*db + e*db**2 + f*wb*db wb = entering wet-bulb temperature seen by the secondary DX coil (C) db = entering dry-bulb temperature seen by the primary DX coil (C) This input field is name of sensible heat ratio modifier biquadratic curve.  The value of this curve modifies the nominal sensible heat ratio for current time step depending on the secondary zone air node wet-bulb temperature and the heating DX coil entering air dry-bulb temperature.  This is an optional input field.  If this input field is left blank, then the nominal sensible heat ratio specified in the field above will be used.
   */
  sensible_heat_ratio_modifier_function_of_temperature_curve_name?: string;
  /**
   * Sensible Heat Ratio Modifier Function of Flow Fraction Curve Name
   * quadratic curve = a + b*ff + c*ff**2 cubic curve = a + b*ff + c*ff**2 + d*ff**3 ff = secondary air flow fraction of the full load flow This input field is name of sensible heat ratio modifier curve.  The value of this curve modifies the nominal sensible heat ratio for current time step depending on the secondary coil air flow fraction. This is an optional input field.  If this input field is left blank, then the nominal sensible heat ratio specified will be used.
   */
  sensible_heat_ratio_modifier_function_of_flow_fraction_curve_name?: string;
}

