/**
 * AirConditioner:VariableRefrigerantFlow:FluidTemperatureControl
 * This is a key object in the new physics based VRF model applicable for Fluid Temperature Control It describes the Variable Refrigerant Flow system excluding the performance of indoor units Indoor units are modeled separately, see ZoneHVAC:TerminalUnit:VariableRefrigerantFlow
 */
export interface AirConditioner_VariableRefrigerantFlow_FluidTemperatureControl {
  /**
   * Heat Pump Name
   * Enter a unique name for this variable refrigerant flow heat pump
   */
  heat_pump_name: string;
  /**
   * Availability Schedule Name
   * Enter the name of a schedule that defines the availability of the unit Schedule values of 0 denote the unit is off. All other values denote the unit is available If this field is left blank, the unit is available the entire simulation
   */
  availability_schedule_name?: string;
  /**
   * Zone Terminal Unit List Name
   * Enter the name of a ZoneTerminalUnitList. This list connects zone terminal units to this heat pump
   */
  zone_terminal_unit_list_name: string;
  /**
   * Refrigerant Type
   * Default: "R410A"
   */
  refrigerant_type?: string;
  /**
   * Rated Evaporative Capacity
   * Enter the total evaporative capacity in watts at rated conditions This is the capacity corresponding to the max compressor speed at rated conditions The actual evaporative capacity is obtained by multiplying the rated capacity with the modification factor calculated by Evaporative Capacity Multiplier Function of Temperature Curve
   * Units: W
   * Default: 40000
   */
  rated_evaporative_capacity?: number | 'Autosize' | 'Autocalculate';
  /**
   * Rated Compressor Power Per Unit of Rated Evaporative Capacity
   * Enter the rated compressor power per Watt of rated evaporative capacity [W/W] Rated compressor power corresponds to the max compressor speed at rated conditions The actual compressor power is obtained by multiplying the rated power with the modification factor calculated by Compressor Power Multiplier Function of Temperature Curve
   * Units: dimensionless
   * Default: 0.35
   */
  rated_compressor_power_per_unit_of_rated_evaporative_capacity?: number;
  /**
   * Minimum Outdoor Air Temperature in Cooling Mode
   * Enter the minimum outdoor temperature allowed for cooling operation Cooling is disabled below this temperature
   * Units: C
   * Default: -6
   */
  minimum_outdoor_air_temperature_in_cooling_mode?: number;
  /**
   * Maximum Outdoor Air Temperature in Cooling Mode
   * Enter the maximum outdoor temperature allowed for cooling operation Cooling is disabled above this temperature
   * Units: C
   * Default: 43
   */
  maximum_outdoor_air_temperature_in_cooling_mode?: number;
  /**
   * Minimum Outdoor Air Temperature in Heating Mode
   * Enter the minimum outdoor temperature allowed for heating operation Heating is disabled below this temperature
   * Units: C
   * Default: -20
   */
  minimum_outdoor_air_temperature_in_heating_mode?: number;
  /**
   * Maximum Outdoor Air Temperature in Heating Mode
   * Enter the maximum outdoor temperature allowed for heating operation Heating is disabled below this temperature
   * Units: C
   * Default: 16
   */
  maximum_outdoor_air_temperature_in_heating_mode?: number;
  /**
   * Reference Outdoor Unit Superheating
   * Units: deltaC
   * Default: 3
   */
  reference_outdoor_unit_superheating?: number;
  /**
   * Reference Outdoor Unit Subcooling
   * Units: deltaC
   * Default: 5
   */
  reference_outdoor_unit_subcooling?: number;
  /**
   * Refrigerant Temperature Control Algorithm for Indoor Unit
   * Default: "VariableTemp"
   */
  refrigerant_temperature_control_algorithm_for_indoor_unit?: 'ConstantTemp' | 'VariableTemp';
  /**
   * Reference Evaporating Temperature for Indoor Unit
   * This field is used if Refrigerant Temperature Control Algorithm is ConstantTemp Evaporating temperature is the refrigerant temperature, not air temperature
   * Units: C
   * Default: 6
   */
  reference_evaporating_temperature_for_indoor_unit?: number;
  /**
   * Reference Condensing Temperature for Indoor Unit
   * This field is used if Refrigerant Temperature Control Algorithm is ConstantTemp Condensing temperature is the refrigerant temperature, not air temperature
   * Units: C
   * Default: 44
   */
  reference_condensing_temperature_for_indoor_unit?: number;
  /**
   * Variable Evaporating Temperature Minimum for Indoor Unit
   * This field is used if Refrigerant Temperature Control Algorithm is VariableTemp Evaporating temperature is the refrigerant temperature, not air temperature
   * Units: C
   * Default: 4
   */
  variable_evaporating_temperature_minimum_for_indoor_unit?: number;
  /**
   * Variable Evaporating Temperature Maximum for Indoor Unit
   * This field is used if Refrigerant Temperature Control Algorithm is VariableTemp Evaporating temperature is the refrigerant temperature, not air temperature
   * Units: C
   * Default: 13
   */
  variable_evaporating_temperature_maximum_for_indoor_unit?: number;
  /**
   * Variable Condensing Temperature Minimum for Indoor Unit
   * This field is used if Refrigerant Temperature Control Algorithm is VariableTemp Condensing temperature is the refrigerant temperature, not air temperature
   * Units: C
   * Default: 42
   */
  variable_condensing_temperature_minimum_for_indoor_unit?: number;
  /**
   * Variable Condensing Temperature Maximum for Indoor Unit
   * This field is used if Refrigerant Temperature Control Algorithm is VariableTemp Condensing temperature is the refrigerant temperature, not air temperature
   * Units: C
   * Default: 46
   */
  variable_condensing_temperature_maximum_for_indoor_unit?: number;
  /**
   * Outdoor Unit Fan Power Per Unit of Rated Evaporative Capacity
   * Enter the outdoor unit fan power per Watt of rated evaporative capacity [W/W]
   * Units: dimensionless
   * Default: 0.00425
   */
  outdoor_unit_fan_power_per_unit_of_rated_evaporative_capacity?: number;
  /**
   * Outdoor Unit Fan Flow Rate Per Unit of Rated Evaporative Capacity
   * This field is only used if the previous is set to autocalculate and performance input method is NominalCapacity
   * Units: m3/s-W
   * Default: 0.000075
   */
  outdoor_unit_fan_flow_rate_per_unit_of_rated_evaporative_capacity?: number;
  /** Outdoor Unit Evaporating Temperature Function of Superheating Curve Name */
  outdoor_unit_evaporating_temperature_function_of_superheating_curve_name: string;
  /** Outdoor Unit Condensing Temperature Function of Subcooling Curve Name */
  outdoor_unit_condensing_temperature_function_of_subcooling_curve_name: string;
  /**
   * Diameter of Main Pipe Connecting Outdoor Unit to the First Branch Joint
   * used to calculate the piping loss
   * Units: m
   * Default: 0.0762
   */
  diameter_of_main_pipe_connecting_outdoor_unit_to_the_first_branch_joint?: number;
  /**
   * Length of Main Pipe Connecting Outdoor Unit to the First Branch Joint
   * used to calculate the heat loss of the main pipe
   * Units: m
   * Default: 30
   */
  length_of_main_pipe_connecting_outdoor_unit_to_the_first_branch_joint?: number;
  /**
   * Equivalent Length of Main Pipe Connecting Outdoor Unit to the First Branch Joint
   * used to calculate the refrigerant pressure drop of the main pipe
   * Units: m
   * Default: 36
   */
  equivalent_length_of_main_pipe_connecting_outdoor_unit_to_the_first_branch_joint?: number;
  /**
   * Height Difference Between Outdoor Unit and Indoor Units
   * Difference between outdoor unit height and indoor unit height Positive means outdoor unit is higher than indoor unit Negative means outdoor unit is lower than indoor unit
   * Units: m
   * Default: 5
   */
  height_difference_between_outdoor_unit_and_indoor_units?: number;
  /**
   * Main Pipe Insulation Thickness
   * Units: m
   * Default: 0.02
   */
  main_pipe_insulation_thickness?: number;
  /**
   * Main Pipe Insulation Thermal Conductivity
   * Units: W/m-K
   * Default: 0.032
   */
  main_pipe_insulation_thermal_conductivity?: number;
  /**
   * Crankcase Heater Power per Compressor
   * Enter the value of the resistive heater located in the compressor(s). This heater is used to warm the refrigerant and oil when the compressor is off
   * Units: W
   * Default: 33
   */
  crankcase_heater_power_per_compressor?: number;
  /**
   * Number of Compressors
   * Enter the total number of compressor. This input is used only for crankcase heater calculations.
   * Units: dimensionless
   * Default: 2
   */
  number_of_compressors?: number;
  /**
   * Ratio of Compressor Size to Total Compressor Capacity
   * Enter the ratio of the first stage compressor to total compressor capacity All other compressors are assumed to be equally sized. This inputs is used only for crankcase heater calculations
   * Units: W/W
   * Default: 0.5
   */
  ratio_of_compressor_size_to_total_compressor_capacity?: number;
  /**
   * Maximum Outdoor Dry-Bulb Temperature for Crankcase Heater
   * Enter the maximum outdoor temperature above which the crankcase heaters are disabled
   * Units: C
   * Default: 5
   */
  maximum_outdoor_dry_bulb_temperature_for_crankcase_heater?: number;
  /**
   * Defrost Strategy
   * Select a defrost strategy. Reverse cycle reverses the operating mode from heating to cooling to melt frost formation on the condenser coil The resistive strategy uses a resistive heater to melt the frost.
   * Default: "Resistive"
   */
  defrost_strategy?: 'Resistive' | 'ReverseCycle';
  /**
   * Defrost Control
   * Choose a defrost control type Either use a fixed Timed defrost period or select OnDemand to defrost only when necessary
   * Default: "Timed"
   */
  defrost_control?: 'OnDemand' | 'Timed';
  /**
   * Defrost Energy Input Ratio Modifier Function of Temperature Curve Name
   * A valid performance curve must be used if ReverseCycle defrost strategy is selected
   */
  defrost_energy_input_ratio_modifier_function_of_temperature_curve_name?: string;
  /**
   * Defrost Time Period Fraction
   * Fraction of time in defrost mode Only applicable if timed defrost control is specified
   * Default: 0.058333
   */
  defrost_time_period_fraction?: number;
  /**
   * Resistive Defrost Heater Capacity
   * Enter the size of the resistive defrost heating element Only applicable if resistive defrost strategy is specified
   * Units: W
   * Default: 0
   */
  resistive_defrost_heater_capacity?: number | 'Autosize' | 'Autocalculate';
  /**
   * Maximum Outdoor Dry-bulb Temperature for Defrost Operation
   * Enter the maximum outdoor temperature above which the defrost operation is disabled
   * Units: C
   * Default: 5
   */
  maximum_outdoor_dry_bulb_temperature_for_defrost_operation?: number;
  /**
   * Compressor maximum delta Pressure
   * Units: Pa
   * Default: 4500000
   */
  compressor_maximum_delta_pressure?: number;
  /**
   * Number of Compressor Loading Index Entries
   * First index represents minimal capacity operation Last index represents full capacity operation
   * Default: 2
   */
  number_of_compressor_loading_index_entries?: number;
  /** Repeating group: compressor_speed_at_loading_index, loading_index_evaporative_capacity_multiplier_function_of_temperature_curve_name, loading_index_compressor_power_multiplier_function_of_temperature_curve_name */
  loading_indices?: ExtensibleGroup[];
}

