/**
 * Pump:VariableSpeed
 * This pump model is described in the ASHRAE secondary HVAC toolkit.
 */
export interface Pump_VariableSpeed {
  /** Inlet Node Name */
  inlet_node_name: string;
  /** Outlet Node Name */
  outlet_node_name: string;
  /**
   * Design Maximum Flow Rate
   * Units: m3/s
   */
  design_maximum_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Pump Head
   * default head is 60 feet
   * Units: Pa
   * Default: 179352
   */
  design_pump_head?: number;
  /**
   * Design Power Consumption
   * When autosized the type of scaling factor is chosen in the input field Design Power Sizing Method
   * Units: W
   */
  design_power_consumption?: number | 'Autosize' | 'Autocalculate';
  /**
   * Motor Efficiency
   * This is the motor efficiency only. When the Design Power Consumption is autosized using PowerPerFlowPerPressure, the Design Shaft Power per Unit Flow Rate per Unit Head is used in addition to the motor efficiency.
   * Default: 0.9
   */
  motor_efficiency?: number;
  /**
   * Fraction of Motor Inefficiencies to Fluid Stream
   * Default: 0
   */
  fraction_of_motor_inefficiencies_to_fluid_stream?: number;
  /**
   * Coefficient 1 of the Part Load Performance Curve
   * Default: 0
   */
  coefficient_1_of_the_part_load_performance_curve?: number;
  /**
   * Coefficient 2 of the Part Load Performance Curve
   * Default: 1
   */
  coefficient_2_of_the_part_load_performance_curve?: number;
  /**
   * Coefficient 3 of the Part Load Performance Curve
   * Default: 0
   */
  coefficient_3_of_the_part_load_performance_curve?: number;
  /**
   * Coefficient 4 of the Part Load Performance Curve
   * Default: 0
   */
  coefficient_4_of_the_part_load_performance_curve?: number;
  /**
   * Design Minimum Flow Rate
   * When autosized the scaling factor is the input field Design Minimum Flow Rate Fraction
   * Units: m3/s
   * Default: "Autosize"
   */
  design_minimum_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Pump Control Type
   * Default: "Continuous"
   */
  pump_control_type?: 'Continuous' | 'Intermittent';
  /**
   * Pump Flow Rate Schedule Name
   * Modifies the rated flow rate of the pump on a time basis. Default is that the pump is on and runs according to its other operational requirements specified above.  The schedule is for special pump operations.
   */
  pump_flow_rate_schedule_name?: string;
  /**
   * Pump Curve Name
   * This references any single independent variable polynomial curve in order to do pressure vs. flow calculations for this pump.  The available types are then: Linear, Quadratic, Cubic, and Quartic The non-dimensional pump pressure relationship is of the following form: (psi = C4*phi^4 + C3*phi^3 + C2*phi^2 + C1*phi + C0) Where the non-dimensional variables are defined as: delP = rho * ((N/60)^2) * (D^2) * psi mdot = rho * (N/60) * (D^3) * phi
   */
  pump_curve_name?: string;
  /**
   * Impeller Diameter
   * "D" in above expression in field A6
   * Units: m
   */
  impeller_diameter?: number;
  /** VFD Control Type */
  vfd_control_type?: 'ManualControl' | 'PressureSetpointControl';
  /**
   * Pump RPM Schedule Name
   * Modifies the rpm of the pump on a time basis. Default is that the pump is on and runs according to its other operational requirements specified above.  The schedule is for special pump operations.
   */
  pump_rpm_schedule_name?: string;
  /**
   * Minimum Pressure Schedule
   * Units: Pa
   */
  minimum_pressure_schedule?: string;
  /**
   * Maximum Pressure Schedule
   * Units: Pa
   */
  maximum_pressure_schedule?: string;
  /**
   * Minimum RPM Schedule
   * Units: rev/min
   */
  minimum_rpm_schedule?: string;
  /**
   * Maximum RPM Schedule
   * Units: rev/min
   */
  maximum_rpm_schedule?: string;
  /**
   * Zone Name
   * optional, if used pump losses transfered to zone as internal gains
   */
  zone_name?: string;
  /**
   * Skin Loss Radiative Fraction
   * optional. If zone identified in previous field then this determines the split between convection and radiation for the skin losses
   */
  skin_loss_radiative_fraction?: number;
  /**
   * Design Power Sizing Method
   * Used to indicate which sizing factor is used to calculate Design Power Consumption. PowerPerFlow indicates that Design Electric Power per Unit Flow Rate is used as scaling factor. Design Power Consumption = Design Maximum Flow Rate * scaling factor PowerPerFlowPerPressure indicates that Design Shaft Power per Unit Flow Rate per Unit Head is used as scaling factor. Design Power Consumption = Design Maximum Flow Rate * Design Pump Head * scaling factor / Motor Efficiency
   * Default: "PowerPerFlowPerPressure"
   */
  design_power_sizing_method?: 'PowerPerFlow' | 'PowerPerFlowPerPressure';
  /**
   * Design Electric Power per Unit Flow Rate
   * Used to size Design Power Consumption from design flow rate
   * Units: W/(m3/s)
   * Default: 348701.1
   */
  design_electric_power_per_unit_flow_rate?: number;
  /**
   * Design Shaft Power per Unit Flow Rate per Unit Head
   * Used to size Design Power Consumption from design flow rate for head and motor efficiency
   * Units: W/((m3/s)-Pa)
   * Default: 1.282051282
   */
  design_shaft_power_per_unit_flow_rate_per_unit_head?: number;
  /**
   * Design Minimum Flow Rate Fraction
   * Used to size Design Minimum Flow Rate
   * Default: 0
   */
  design_minimum_flow_rate_fraction?: number;
  /**
   * End-Use Subcategory
   * Any text may be used here to categorize the end-uses in the ABUPS End Uses by Subcategory table.
   * Default: "General"
   */
  end_use_subcategory?: string;
}

