/**
 * EvaporativeFluidCooler:SingleSpeed
 * This model is based on Merkel's theory, which is also the basis for the cooling tower model in EnergyPlus. The Evaporative fluid cooler is modeled as a counter flow heat exchanger.
 */
export interface EvaporativeFluidCooler_SingleSpeed {
  /**
   * Water Inlet Node Name
   * Name of Fluid Cooler water inlet node
   */
  water_inlet_node_name: string;
  /**
   * Water Outlet Node Name
   * Name of Fluid Cooler water outlet node
   */
  water_outlet_node_name: string;
  /**
   * Design Air Flow Rate
   * Units: m3/s
   */
  design_air_flow_rate: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Air Flow Rate Fan Power
   * This is the fan motor electric input power
   * Units: W
   */
  design_air_flow_rate_fan_power: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Spray Water Flow Rate
   * Units: m3/s
   */
  design_spray_water_flow_rate: number;
  /**
   * Performance Input Method
   * User can define fluid cooler thermal performance by specifying the fluid cooler UA and the Design Water Flow Rate, or by specifying the fluid cooler Standard Design Capacity or by specifying Design Capacity for Non standard conditions.
   */
  performance_input_method?:
    | 'StandardDesignCapacity'
    | 'UFactorTimesAreaAndDesignWaterFlowRate'
    | 'UserSpecifiedDesignCapacity';
  /**
   * Outdoor Air Inlet Node Name
   * Enter the name of an outdoor air node
   */
  outdoor_air_inlet_node_name?: string;
  /**
   * Heat Rejection Capacity and Nominal Capacity Sizing Ratio
   * Default: 1.25
   */
  heat_rejection_capacity_and_nominal_capacity_sizing_ratio?: number;
  /**
   * Standard Design Capacity
   * Standard design capacity with entering water at 35C (95F), leaving water at 29.44C (85F), entering air at 25.56C (78F) wet-bulb temperature and 35C (95F) dry-bulb temperature. Design water flow rate assumed to be 5.382E-8 m3/s per watt (3 gpm/ton). Standard design capacity times the Heat Rejection Capacity and Nominal Capacity Sizing Ratio (e.g. 1.25) gives the actual fluid cooler heat rejection at these operating conditions. Only used for Performance Input Method = StandardDesignCapacity; for other input methods, this field is ignored. The standard conditions mentioned above for Standard design capacity are already specified in the EnergyPlus. So the input fields such as design entering water temp., design entering air wet-bulb and dry-bulb temp. and design water flow rate, if provided in the input, will be ignored for the StandardDesignCapacity performance input method. Also, the standard conditions are for water as a fluid type so this performance input method can only be used with water as a fluid type (as specified in CondenserLoop object).
   * Units: W
   */
  standard_design_capacity?: number;
  /**
   * Design Air Flow Rate U-factor Times Area Value
   * Only used for Performance Input Method = UFactorTimesAreaAndDesignWaterFlowRate; for other Performance Input Methods, this field is ignored.
   * Units: W/K
   */
  design_air_flow_rate_u_factor_times_area_value?: number | 'Autosize' | 'Autocalculate';
  /**
   * Design Water Flow Rate
   * Input value is ignored if fluid cooler Performance Input Method= StandardDesignCapacity.
   * Units: m3/s
   */
  design_water_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * User Specified Design Capacity
   * Only used for Performance Input Method = UserSpecifiedDesignCapacity; for other Performance Input Methods, this field is ignored.
   * Units: W
   */
  user_specified_design_capacity?: number;
  /**
   * Design Entering Water Temperature
   * Only used for Performance Input Method = UserSpecifiedDesignCapacity; for other Performance Input Methods, this field is ignored. Design Entering Water Temperature must be greater than Design Entering Air Temperature.
   * Units: C
   */
  design_entering_water_temperature?: number;
  /**
   * Design Entering Air Temperature
   * Only used for Performance Input Method = UserSpecifiedDesignCapacity; for other Performance Input Methods, this field is ignored. Design Entering Air Temperature must be greater than Design Entering Air Wet-bulb Temperature.
   * Units: C
   */
  design_entering_air_temperature?: number;
  /**
   * Design Entering Air Wet-bulb Temperature
   * Only used for Performance Input Method = UserSpecifiedDesignCapacity; for other Performance Input Methods, this field is ignored. Design Entering Air Wet-bulb Temperature must be less than Design Entering Air Temperature.
   * Units: C
   */
  design_entering_air_wet_bulb_temperature?: number;
  /**
   * Capacity Control
   * Default: "FanCycling"
   */
  capacity_control?: 'FanCycling' | 'FluidBypass';
  /**
   * Sizing Factor
   * Multiplies the autosized capacity and flow rates
   * Default: 1
   */
  sizing_factor?: number;
  /**
   * Evaporation Loss Mode
   * Default: "SaturatedExit"
   */
  evaporation_loss_mode?: 'LossFactor' | 'SaturatedExit';
  /**
   * Evaporation Loss Factor
   * Rate of water evaporation from the Fluid Cooler and lost to the outdoor air [%/K] Empirical correlation is used to calculate default loss factor if it not explicitly provided.
   * Units: percent/K
   */
  evaporation_loss_factor?: number;
  /**
   * Drift Loss Percent
   * Rate of drift loss as a percentage of circulating spray water flow rate Default value for this field is under investigation. For now Cooling tower's drift loss percent default value is taken here.
   * Units: percent
   * Default: 0.008
   */
  drift_loss_percent?: number;
  /**
   * Blowdown Calculation Mode
   * Default: "ConcentrationRatio"
   */
  blowdown_calculation_mode?: 'ConcentrationRatio' | 'ScheduledRate';
  /**
   * Blowdown Concentration Ratio
   * Characterizes the rate of blowdown in the Evaporative Fluid Cooler. Blowdown is water intentionally drained from the basin in order to offset the build up of solids in the water that would otherwise occur because of evaporation. Ratio of solids in the blowdown water to solids in the make up water. Default value for this field is under investigation. For now Cooling tower's Blowdown Concentration Ratio percent default value is taken here.
   * Default: 3
   */
  blowdown_concentration_ratio?: number;
  /**
   * Blowdown Makeup Water Usage Schedule Name
   * Makeup water usage due to blowdown results from occasionally draining a small amount of water in the Fluid Cooler basin to purge scale or other contaminants to reduce their concentration in order to maintain an acceptable level of water quality. Schedule values should reflect water usage in m3/s.
   */
  blowdown_makeup_water_usage_schedule_name?: string;
  /** Supply Water Storage Tank Name */
  supply_water_storage_tank_name?: string;
}

