  inlet_mode?: 'Fixed' | 'Seeking';
  /**
   * Use Side Design Flow Rate
   * Units: m3/s
   * Default: "Autosize"
   */
  use_side_design_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Source Side Design Flow Rate
   * Units: m3/s
   * Default: "Autosize"
   */
  source_side_design_flow_rate?: number | 'Autosize' | 'Autocalculate';
  /**
   * Indirect Water Heating Recovery Time
   * Parameter for autosizing design flow rates for indirectly heated water tanks time required to raise temperature of entire tank from 14.4C to 57.2C
   * Units: hr
   * Default: 1.5
   */
  indirect_water_heating_recovery_time?: number;
  /**
   * Number of Nodes
   * Default: 1
   */
  number_of_nodes?: number;
  /**
   * Additional Destratification Conductivity
   * Units: W/m-K
   * Default: 0
   */
