/**
 * Generator:InternalCombustionEngine
 * This generator model is the empirical model from the Building Loads and System Thermodynamics (BLAST) program.  Engine performance curves are generated by fitting catalog data to second order polynomial equations.  Three sets of coefficients are required.
 */
export interface Generator_InternalCombustionEngine {
  /**
   * Rated Power Output
   * Units: W
   */
  rated_power_output?: number;
  /** Electric Circuit Node Name */
  electric_circuit_node_name?: string;
  /** Minimum Part Load Ratio */
  minimum_part_load_ratio?: number;
  /** Maximum Part Load Ratio */
  maximum_part_load_ratio?: number;
  /** Optimum Part Load Ratio */
  optimum_part_load_ratio?: number;
  /**
   * Shaft Power Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output
   */
  shaft_power_curve_name?: string;
  /**
   * Jacket Heat Recovery Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output
   */
  jacket_heat_recovery_curve_name?: string;
  /**
   * Lube Heat Recovery Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output
   */
  lube_heat_recovery_curve_name?: string;
  /**
   * Total Exhaust Energy Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output
   */
  total_exhaust_energy_curve_name?: string;
  /**
   * Exhaust Temperature Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output
   */
  exhaust_temperature_curve_name?: string;
  /**
   * Coefficient 1 of U-Factor Times Area Curve
   * curve = C1 * Generator Rated Power Output**C2
   */
  coefficient_1_of_u_factor_times_area_curve?: number;
  /**
   * Coefficient 2 of U-Factor Times Area Curve
   * curve = C1 * Generator Rated Power Output**C2 typical value .9
   */
  coefficient_2_of_u_factor_times_area_curve?: number;
  /**
   * Maximum Exhaust Flow per Unit of Power Output
   * Units: (kg/s)/W
   */
  maximum_exhaust_flow_per_unit_of_power_output?: number;
  /**
   * Design Minimum Exhaust Temperature
   * Units: C
   */
  design_minimum_exhaust_temperature?: number;
  /**
   * Fuel Higher Heating Value
   * Units: kJ/kg
   */
  fuel_higher_heating_value?: number;
  /**
   * Design Heat Recovery Water Flow Rate
   * if non-zero, then inlet, outlet nodes must be entered.
   * Units: m3/s
   * Default: 0
   */
  design_heat_recovery_water_flow_rate?: number;
  /** Heat Recovery Inlet Node Name */
  heat_recovery_inlet_node_name?: string;
  /** Heat Recovery Outlet Node Name */
  heat_recovery_outlet_node_name?: string;
  /**
   * Fuel Type
   * Default: "Diesel"
   */
  fuel_type?:
    | 'Diesel'
    | 'FuelOilNo1'
    | 'FuelOilNo2'
    | 'Gasoline'
    | 'NaturalGas'
    | 'OtherFuel1'
    | 'OtherFuel2'
    | 'Propane';
  /**
   * Heat Recovery Maximum Temperature
   * Units: C
   * Default: 80
   */
  heat_recovery_maximum_temperature?: number;
}

/**
 * Generator:CombustionTurbine
 * This generator model is the empirical model from the Building Loads and System Thermodynamics (BLAST) program.  Generator performance curves are generated by fitting catalog data to second order polynomial equations.  Three sets of coefficients are required.
 */
export interface Generator_CombustionTurbine {
  /**
   * Rated Power Output
   * Units: W
   */
  rated_power_output?: number;
  /** Electric Circuit Node Name */
  electric_circuit_node_name?: string;
  /** Minimum Part Load Ratio */
  minimum_part_load_ratio?: number;
  /** Maximum Part Load Ratio */
  maximum_part_load_ratio?: number;
  /** Optimum Part Load Ratio */
  optimum_part_load_ratio?: number;
  /**
   * Part Load Based Fuel Input Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output this curve is multiplied to the Temperature Based Fuel Input Curve to determine Fuel Energy In
   */
  part_load_based_fuel_input_curve_name?: string;
  /**
   * Temperature Based Fuel Input Curve Name
   * curve = a + b*AT + c*AT**2 AT = Ambient Delta T this curve is multiplied to the Part Load Based Fuel Input Curve to determine Fuel Energy In
   */
  temperature_based_fuel_input_curve_name?: string;
  /**
   * Exhaust Flow Curve Name
   * curve = a + b*AT + c*AT**2 AT = Ambient Delta T
   */
  exhaust_flow_curve_name?: string;
  /**
   * Part Load Based Exhaust Temperature Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output this curve is multiplied to the Temperature Based Exhaust Temperature Curve to determine Exhaust Temperature
   */
  part_load_based_exhaust_temperature_curve_name?: string;
  /**
   * Temperature Based Exhaust Temperature Curve Name
   * curve = a + b*AT + c*AT**2 AT = Ambient Delta T this curve is multiplied to the Part Load Based Exhaust Temperature Curve to determine Exhaust Temperature
   */
  temperature_based_exhaust_temperature_curve_name?: string;
  /**
   * Heat Recovery Lube Energy Curve Name
   * curve = a + b*PLR + c*PLR**2 PLR = Ratio of Generator Load to Rated Power Output
   */
  heat_recovery_lube_energy_curve_name?: string;
  /**
   * Coefficient 1 of U-Factor Times Area Curve
   * curve = C1 * Rated Power Output**C2
   */
  coefficient_1_of_u_factor_times_area_curve?: number;
  /**
   * Coefficient 2 of U-Factor Times Area Curve
   * curve = C1 * Rated Power Output**C2 typical value .9
   */
  coefficient_2_of_u_factor_times_area_curve?: number;
  /**
   * Maximum Exhaust Flow per Unit of Power Output
   * Units: (kg/s)/W
   */
  maximum_exhaust_flow_per_unit_of_power_output?: number;
  /**
   * Design Minimum Exhaust Temperature
   * Units: C
   */
  design_minimum_exhaust_temperature?: number;
  /**
   * Design Air Inlet Temperature
   * Units: C
   */
  design_air_inlet_temperature?: number;
  /**
   * Fuel Higher Heating Value
   * Units: kJ/kg
   */
  fuel_higher_heating_value?: number;
  /**
   * Design Heat Recovery Water Flow Rate
   * if non-zero, then inlet, outlet nodes must be entered.
   * Units: m3/s
   * Default: 0
   */
  design_heat_recovery_water_flow_rate?: number;
  /** Heat Recovery Inlet Node Name */
  heat_recovery_inlet_node_name?: string;
  /** Heat Recovery Outlet Node Name */
  heat_recovery_outlet_node_name?: string;
  /**
   * Fuel Type
   * Default: "NaturalGas"
   */
  fuel_type?:
    | 'Diesel'
    | 'FuelOilNo1'
    | 'FuelOilNo2'
    | 'Gasoline'
    | 'NaturalGas'
    | 'OtherFuel1'
    | 'OtherFuel2'
    | 'Propane';
  /**
   * Heat Recovery Maximum Temperature
   * Units: C
   * Default: 80
   */
  heat_recovery_maximum_temperature?: number;
  /**
   * Outdoor Air Inlet Node Name
   * Enter the name of an outdoor air node
   */
  outdoor_air_inlet_node_name?: string;
}

/**
 * Generator:MicroTurbine
 * MicroTurbine generators are small combustion turbines (e.g., 25kW to 500kW). The model calculates electrical power output, fuel use, standby and ancillary power. Energy recovery from exhaust air can be used to heat water.
 */
export interface Generator_MicroTurbine {
  /**
   * Reference Electrical Power Output
   * Units: W
   */
  reference_electrical_power_output: number;
  /**
   * Minimum Full Load Electrical Power Output
   * Units: W
   * Default: 0
   */
  minimum_full_load_electrical_power_output?: number;
  /**
   * Maximum Full Load Electrical Power Output
   * If left blank, Maximum Full Load Electrical Power Output will be set equal to the Reference Electrical Power Output.
   * Units: W
   */
  maximum_full_load_electrical_power_output?: number;
  /**
   * Reference Electrical Efficiency Using Lower Heating Value
   * Electric power output divided by fuel energy input (LHV basis) at reference conditions.
   */
  reference_electrical_efficiency_using_lower_heating_value: number;
  /**
   * Reference Combustion Air Inlet Temperature
   * Units: C
   * Default: 15
   */
  reference_combustion_air_inlet_temperature?: number;
  /**
   * Reference Combustion Air Inlet Humidity Ratio
   * Units: kgWater/kgDryAir
   * Default: 0.00638
   */
  reference_combustion_air_inlet_humidity_ratio?: number;
  /**
   * Reference Elevation
   * Units: m
   * Default: 0
   */
  reference_elevation?: number;
  /**
   * Electrical Power Function of Temperature and Elevation Curve Name
   * curve = a + b*T + c*T**2 + d*Elev + e*Elev**2 + f*T*Elev T = combustion air inlet temperature (C) Elev = elevation (m)
   */
  electrical_power_function_of_temperature_and_elevation_curve_name: string;
  /**
   * Electrical Efficiency Function of Temperature Curve Name
   * Quadratic curve = a + b*T + c*T**2 Cubic curve = a + b*T + c*T**2 + d*T**3 T = combustion air inlet temperature (C)
   */
  electrical_efficiency_function_of_temperature_curve_name: string;
  /**
   * Electrical Efficiency Function of Part Load Ratio Curve Name
   * Quadratic curve = a + b*PLR + c*PLR**2 Cubic curve = a + b*PLR + c*PLR**2 + d*PLR**3 PLR = ratio of Generator Load to steady state Electrical Power Output at current operating conditions
   */
  electrical_efficiency_function_of_part_load_ratio_curve_name: string;
  /**
   * Fuel Type
   * Default: "NaturalGas"
   */
  fuel_type?: 'NaturalGas' | 'Propane';
  /**
   * Fuel Higher Heating Value
   * Units: kJ/kg
   * Default: 50000
   */
  fuel_higher_heating_value?: number;
  /**
   * Fuel Lower Heating Value
   * Units: kJ/kg
   * Default: 45450
   */
  fuel_lower_heating_value?: number;
  /**
   * Standby Power
   * Electric power consumed when the generator is available but not being called by the Electric Load Center.
   * Units: W
   * Default: 0
   */
  standby_power?: number;
  /**
   * Ancillary Power
   * Electric power consumed by ancillary equipment (e.g., external fuel pressurization pump). Set to zero if Reference Electrical Power Output is the 'net' value (ancillary power already deducted). Input value is positive, but indicates negative electric generation.
   * Units: W
   * Default: 0
   */
  ancillary_power?: number;
  /**
   * Ancillary Power Function of Fuel Input Curve Name
   * Quadratic curve = a + b*mdot + c*mdot**2 mdot = fuel mass flow rate (kg/s) If left blank, model assumes ancillary power defined in previous field is constant whenever the generator is operating.
   */
  ancillary_power_function_of_fuel_input_curve_name?: string;
  /** Heat Recovery Water Inlet Node Name */
  heat_recovery_water_inlet_node_name?: string;
  /** Heat Recovery Water Outlet Node Name */
  heat_recovery_water_outlet_node_name?: string;
  /**
   * Reference Thermal Efficiency Using Lower Heat Value
   * Reference thermal efficiency (heat recovery to water) based on the Lower Heating Value (LHV) of the fuel.
   * Default: 0
   */
  reference_thermal_efficiency_using_lower_heat_value?: number;
  /**
   * Reference Inlet Water Temperature
   * Units: C
   */
  reference_inlet_water_temperature?: number;
  /**
   * Heat Recovery Water Flow Operating Mode
   * PlantControl means the heat recovery water flow rate is determined by the plant, but the user needs to supply a heat recovery water flow rate. InternalControl means the heat recovery water flow rate is controlled by this generator. If 'InternalControl' is selected, then the user needs to supply a reference heat recovery water flow rate and optionally the name of a heat recovery flow rate modifier curve.
   * Default: "PlantControl"
   */
  heat_recovery_water_flow_operating_mode?: 'InternalControl' | 'PlantControl';
  /**
   * Reference Heat Recovery Water Flow Rate
   * Units: m3/s
   */
  reference_heat_recovery_water_flow_rate?: number;
  /**
   * Heat Recovery Water Flow Rate Function of Temperature and Power Curve Name
   * curve = a + b*T + c*T**2 + d*Pnet + e*Pnet + f*T*Pnet T = heat recovery inlet water temperature Pnet = net power output = electric power output - ancillary power If left blank, model assumes the heat recovery water flow rate is constant whenever the generator is operating, at the Reference HR Water Flow Rate defined in the previous field.
   */
  heat_recovery_water_flow_rate_function_of_temperature_and_power_curve_name?: string;
  /**
   * Thermal Efficiency Function of Temperature and Elevation Curve Name
   * Bicubic curve = a + b*T + c*T**2 + d*Elev + e*Elev**2 + f*T*Elev + g*T**3 + h*Elev**3 + i*T**2*Elev + j*T*Elev**2 Biquadratic curve = a + b*T + c*T**2 + d*Elev + e*Elev**2 + f*T*Elev T = combustion air inlet temperature (C) Elev = elevation (m) If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  thermal_efficiency_function_of_temperature_and_elevation_curve_name?: string;
  /**
   * Heat Recovery Rate Function of Part Load Ratio Curve Name
   * Quadratic curve = a + b*PLR + c*PLR**2 Cubic curve = a + b*PLR + c*PLR**2 + d*PLR**3 PLR = ratio of Generator Load to steady state Electrical Power Output at current operating conditions If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  heat_recovery_rate_function_of_part_load_ratio_curve_name?: string;
  /**
   * Heat Recovery Rate Function of Inlet Water Temperature Curve Name
   * Quadratic curve = a + b*T + c*T**2 T = inlet water temperature (C) If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  heat_recovery_rate_function_of_inlet_water_temperature_curve_name?: string;
  /**
   * Heat Recovery Rate Function of Water Flow Rate Curve Name
   * Quadratic curve = a + b*Flow + c*Flow**2 Flow = flow rate of water through the heat exchanger (m3/s) If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  heat_recovery_rate_function_of_water_flow_rate_curve_name?: string;
  /**
   * Minimum Heat Recovery Water Flow Rate
   * Units: m3/s
   * Default: 0
   */
  minimum_heat_recovery_water_flow_rate?: number;
  /**
   * Maximum Heat Recovery Water Flow Rate
   * Units: m3/s
   * Default: 0
   */
  maximum_heat_recovery_water_flow_rate?: number;
  /**
   * Maximum Heat Recovery Water Temperature
   * Units: C
   */
  maximum_heat_recovery_water_temperature?: number;
  /**
   * Combustion Air Inlet Node Name
   * Must be an outdoor air node.
   */
  combustion_air_inlet_node_name?: string;
  /** Combustion Air Outlet Node Name */
  combustion_air_outlet_node_name?: string;
  /**
   * Reference Exhaust Air Mass Flow Rate
   * Units: kg/s
   */
  reference_exhaust_air_mass_flow_rate?: number;
  /**
   * Exhaust Air Flow Rate Function of Temperature Curve Name
   * Quadratic curve = a + b*T + c*T**2 Cubic curve = a + b*T + c*T**2 + d*T**3 T = combustion air inlet temperature (C) If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  exhaust_air_flow_rate_function_of_temperature_curve_name?: string;
  /**
   * Exhaust Air Flow Rate Function of Part Load Ratio Curve Name
   * Quadratic curve = a + b*PLR + c*PLR**2 Cubic curve = a + b*PLR + c*PLR**2 + d*PLR**3 PLR = ratio of Generator Load to steady state Electrical Power Output at current operating conditions. If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  exhaust_air_flow_rate_function_of_part_load_ratio_curve_name?: string;
  /**
   * Nominal Exhaust Air Outlet Temperature
   * Exhaust air outlet temperature at reference conditions.
   */
  nominal_exhaust_air_outlet_temperature?: number;
  /**
   * Exhaust Air Temperature Function of Temperature Curve Name
   * Quadratic curve = a + b*T + c*T**2 Cubic curve = a + b*T + c*T**2 + d*T**3 T = combustion air inlet temperature (C) If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  exhaust_air_temperature_function_of_temperature_curve_name?: string;
  /**
   * Exhaust Air Temperature Function of Part Load Ratio Curve Name
   * Quadratic curve = a + b*PLR + c*PLR**2 Cubic curve = a + b*PLR + c*PLR**2 + d*PLR**3 PLR = ratio of Generator Load to steady state Electrical Power Output at current operating conditions. If field is left blank, model assumes this modifier equals 1 for entire simulation.
   */
  exhaust_air_temperature_function_of_part_load_ratio_curve_name?: string;
}

/**
 * Generator:Photovoltaic
 * Describes an array of photovoltaic (PV) modules.  A series of different PV arrays can be connected to a single electric load center (and inverter) by listing them all in an ElectricLoadCenter:Generator object. PV performance is taken from the referenced PhotovoltaicPerformance:* object. Array tilt, azimuth, and gross area are taken from the referenced building surface or shading surface. The array surface participates normally in all shading calculations.
 */
export interface Generator_Photovoltaic {
  /** Surface Name */
  surface_name: string;
  /** Photovoltaic Performance Object Type */
  photovoltaic_performance_object_type?:
    | 'PhotovoltaicPerformance:EquivalentOne-Diode'
    | 'PhotovoltaicPerformance:Sandia'
    | 'PhotovoltaicPerformance:Simple';
  /**
   * Module Performance Name
   * PV array modeling details
   */
  module_performance_name?: string;
  /**
   * Heat Transfer Integration Mode
   * Default: "Decoupled"
   */
  heat_transfer_integration_mode?:
    | 'Decoupled'
    | 'DecoupledUllebergDynamic'
    | 'IntegratedExteriorVentedCavity'
    | 'IntegratedSurfaceOutsideFace'
    | 'IntegratedTranspiredCollector'
    | 'PhotovoltaicThermalSolarCollector';
  /**
   * Number of Series Strings in Parallel
   * number of series-wired strings of PV modules that are in parallel
   * Units: dimensionless
   * Default: 1
   */
  number_of_series_strings_in_parallel?: number;
  /**
   * Number of Modules in Series
   * Number of PV modules wired in series for each string.
   * Units: dimensionless
   * Default: 1
   */
  number_of_modules_in_series?: number;
}

/**
 * PhotovoltaicPerformance:Simple
 * Describes a simple model of photovoltaics that may be useful for early phase design analysis. In this model the user has direct access to the efficiency with which surfaces convert incident solar radiation to electricity and need not specify arrays of specific modules.
 */
export interface PhotovoltaicPerformance_Simple {
  /**
   * Fraction of Surface Area with Active Solar Cells
   * Units: dimensionless
   */
  fraction_of_surface_area_with_active_solar_cells: number;
  /** Conversion Efficiency Input Mode */
  conversion_efficiency_input_mode?: 'Fixed' | 'Scheduled';
  /**
   * Value for Cell Efficiency if Fixed
   * Efficiency = (power generated [W])/(incident solar[W])
   */
  value_for_cell_efficiency_if_fixed?: number;
  /** Efficiency Schedule Name */
  efficiency_schedule_name?: string;
}

/**
 * PhotovoltaicPerformance:EquivalentOne-Diode
 * Describes the performance characteristics of Photovoltaic (PV) modules to be modeled using an equivalent one-diode circuit.  This model is also known as the 4- or 5-parameter TRNSYS model for photovoltaics.
 */
export interface PhotovoltaicPerformance_EquivalentOne_Diode {
  /** Cell type */
  cell_type?: 'AmorphousSilicon' | 'CrystallineSilicon';
  /**
   * Number of Cells in Series
   * Units: dimensionless
   * Default: 36
   */
  number_of_cells_in_series?: number;
  /**
   * Active Area
   * The total power output of the array is determined by the number of modules (see above).  The Active Area is only used to calculate the PV Array Efficiency output variable.
   * Units: m2
   * Default: 0.89
   */
  active_area?: number;
  /**
   * Transmittance Absorptance Product
   * Units: dimensionless
   * Default: 0.95
   */
  transmittance_absorptance_product?: number;
  /**
   * Semiconductor Bandgap
   * Units: eV
   * Default: 1.12
   */
  semiconductor_bandgap?: number;
  /**
   * Shunt Resistance
   * Units: ohms
   * Default: 1000000
   */
  shunt_resistance?: number;
  /**
   * Short Circuit Current
   * Units: A
   * Default: 6.5
   */
  short_circuit_current?: number;
  /**
   * Open Circuit Voltage
   * Units: V
   * Default: 21.6
   */
  open_circuit_voltage?: number;
  /**
   * Reference Temperature
   * Units: C
   * Default: 25
   */
  reference_temperature?: number;
  /**
   * Reference Insolation
   * Units: W/m2
   * Default: 1000
   */
  reference_insolation?: number;
  /**
   * Module Current at Maximum Power
   * Single module current at the maximum power point and reference conditions.  Module Current, Module Voltage, Number of Modules in Parallel and Number of Modules in Series determine the maximum power output of the array.
   * Units: A
   * Default: 5.9
   */
  module_current_at_maximum_power?: number;
  /**
   * Module Voltage at Maximum Power
   * Single module voltage at the maximum power point and reference conditions.  Module Current, Module Voltage, Number of Modules in Parallel and Number of Modules in Series determine the maximum power output of the array.
   * Units: V
   * Default: 17
   */
  module_voltage_at_maximum_power?: number;
  /**
   * Temperature Coefficient of Short Circuit Current
   * Units: A/K
   * Default: 0.02
   */
  temperature_coefficient_of_short_circuit_current?: number;
  /**
   * Temperature Coefficient of Open Circuit Voltage
   * Units: V/K
   * Default: -0.079
   */
  temperature_coefficient_of_open_circuit_voltage?: number;
  /**
   * Nominal Operating Cell Temperature Test Ambient Temperature
   * Units: C
   * Default: 20
   */
  nominal_operating_cell_temperature_test_ambient_temperature?: number;
  /**
   * Nominal Operating Cell Temperature Test Cell Temperature
   * Units: C
   * Default: 40
   */
  nominal_operating_cell_temperature_test_cell_temperature?: number;
  /**
   * Nominal Operating Cell Temperature Test Insolation
   * Units: W/m2
   * Default: 800
   */
  nominal_operating_cell_temperature_test_insolation?: number;
  /**
   * Module Heat Loss Coefficient
   * Units: W/m2-K
   * Default: 30
   */
  module_heat_loss_coefficient?: number;
  /**
   * Total Heat Capacity
   * Units: J/m2-K
   * Default: 50000
   */
  total_heat_capacity?: number;
}

