/**
 * HybridModel:Zone
 * Zones with measured air temperature data and a range of dates. If the range of temperature measurement dates includes a leap day, the weather data should include a leap day.
 */
export interface HybridModel_Zone {
  /** Zone Name */
  zone_name: string;
  /**
   * Calculate Zone Internal Thermal Mass
   * Use measured zone air temperature to calculate zone internal thermal mass. If set to Yes, the measured zone air temperature should be provided to calculate the thermal mass. If set to No, the inverse calculation of thermal mass will not be activated.
   * Default: "No"
   */
  calculate_zone_internal_thermal_mass?: 'No' | 'Yes';
  /**
   * Calculate Zone Air Infiltration Rate
   * Use measured temperature data (temperature, humidity ratio, or CO2 concentration) to calculate zone air infiltration air flow rate. Only one of field Calculate Zone Internal Thermal Mass, Calculate Zone Air Infiltration Rate, and Calculate Zone People Count can be set to YES at a time. By default, this field is set to NO. When set to NO, the inverse calculation of the zone air infiltration rate will not be activated. If this field is set to YES, one of the following fields (combinations) should be provided: 1. Measurements were conducted when HVAC is free-floating: 1.1 Zone Measured Air Temperature Schedule Name 1.2 Zone Measured Air Humidity Ratio Schedule Name 1.3 Zone Measured Air CO2 Concentration Schedule Name 2. Measurements were conducted when HVAC is on: 2.1 Zone Measured Air Temperature Schedule Name, Zone Input Supply Air Temperature Schedule Name, and Zone Input Supply Air Mass Flow Rate Schedule Name 2.2 Zone Measured Air Humidity Ratio Schedule Name, Zone Input Supply Air Temperature Schedule Name, Zone Input Supply Air Mass Flow Rate Schedule Name, and Zone Input Supply Air Humidity Ratio Schedule Name 2.3 Zone Measured Air CO2 Concentration Schedule Name, Zone Input Supply Air Mass Flow Rate Schedule Name, and Zone Input Supply Air CO2 Concentration Schedule Name
   * Default: "No"
   */
  calculate_zone_air_infiltration_rate?: 'No' | 'Yes';
  /**
   * Calculate Zone People Count
   * Use measured humidity ratio data (temperature, humidity ratio, or CO2 concentration) to calculate zone people count. Only one of field Calculate Zone Internal Thermal Mass, Calculate Zone Air Infiltration Rate, and Calculate Zone People Count can be set to YES at a time. By default, this field is set to NO. When set to NO, the inverse calculation of the zone people count will not be activated. If this field is set to YES, one of the following fields (combinations) should be provided: 1. Measurements were conducted when HVAC is free-floating: 1.1 Zone Measured Air Temperature Schedule Name 1.2 Zone Measured Air Humidity Ratio Schedule Name 1.3 Zone Measured Air CO2 Concentration Schedule Name 2. Measurements were conducted when HVAC is on: 2.1 Zone Measured Air Temperature Schedule Name, Zone Input Supply Air Temperature Schedule Name, and Zone Input Supply Air Mass Flow Rate Schedule Name 2.2 Zone Measured Air Humidity Ratio Schedule Name, Zone Input Supply Air Temperature Schedule Name, Zone Input Supply Air Mass Flow Rate Schedule Name, and Zone Input Supply Air Humidity Ratio Schedule Name 2.3 Zone Measured Air CO2 Concentration Schedule Name, Zone Input Supply Air Mass Flow Rate Schedule Name, and Zone Input Supply Air CO2 Concentration Schedule Name Field Zone Input People Activity Schedule Name, Zone Input People Sensible Heat Fraction Schedule Name, Zone Input People Radiant Heat Fraction Schedule Name, Zone Input People CO2 Generation Rate Schedule Name are optional. If provided, the default people activity level (130W), sensible heat generation rate (78W), latent heat generation (52W) rate, and CO2 generation rate (0.0000000382 [m3/(s*W)]) will be overwritten correspondingly.
   * Default: "No"
   */
  calculate_zone_people_count?: 'No' | 'Yes';
  /**
   * Zone Measured Air Temperature Schedule Name
   * from Schedule:File
   */
  zone_measured_air_temperature_schedule_name?: string;
  /**
   * Zone Measured Air Humidity Ratio Schedule Name
   * from Schedule:File
   */
  zone_measured_air_humidity_ratio_schedule_name?: string;
  /**
   * Zone Measured Air CO2 Concentration Schedule Name
   * from Schedule:File
   */
  zone_measured_air_co2_concentration_schedule_name?: string;
  /**
   * Zone Input People Activity Schedule Name
   * When this field is provided and valid, the default people activity level (used to calculate people count) will be overwritten. from Schedule:File
   */
  zone_input_people_activity_schedule_name?: string;
  /**
   * Zone Input People Sensible Heat Fraction Schedule Name
   * When this field is provided and valid, the default sensible heat fraction from people (used to calculate people count) will be overwritten. from Schedule:File
   */
  zone_input_people_sensible_heat_fraction_schedule_name?: string;
  /**
   * Zone Input People Radiant Heat Fraction Schedule Name
   * When this field is provided and valid, the default radiant heat portion of the sensible heat from people (used to calculate people count) will be overwritten. from Schedule:File
   */
  zone_input_people_radiant_heat_fraction_schedule_name?: string;
  /**
   * Zone Input People CO2 Generation Rate Schedule Name
   * When this field is provided and valid, the default people CO2 generation rate (used to calculate people count) will be overwritten. from Schedule:File
   */
  zone_input_people_co2_generation_rate_schedule_name?: string;
  /**
   * Zone Input Supply Air Temperature Schedule Name
   * from Schedule:File
   */
  zone_input_supply_air_temperature_schedule_name?: string;
  /**
   * Zone Input Supply Air Mass Flow Rate Schedule Name
   * from Schedule:File
   */
  zone_input_supply_air_mass_flow_rate_schedule_name?: string;
  /**
   * Zone Input Supply Air Humidity Ratio Schedule Name
   * from Schedule:File
   */
  zone_input_supply_air_humidity_ratio_schedule_name?: string;
  /**
   * Zone Input Supply Air CO2 Concentration Schedule Name
   * from Schedule:File
   */
  zone_input_supply_air_co2_concentration_schedule_name?: string;
  /** Begin Month */
  begin_month: number;
  /** Begin Day of Month */
  begin_day_of_month: number;
  /** End Month */
  end_month: number;
  /** End Day of Month */
  end_day_of_month: number;
}

/**
 * Curve:Linear
 * Linear curve with one independent variable. Input for the linear curve consists of a curve name, the two coefficients, and the maximum and minimum valid independent variable values. Optional inputs for curve minimum and maximum may be used to limit the output of the performance curve. curve = C1 + C2*x
 */
export interface Curve_Linear {
  /** Coefficient1 Constant */
  coefficient1_constant: number;
  /** Coefficient2 x */
  coefficient2_x: number;
  /** Minimum Value of x */
  minimum_value_of_x: number;
  /** Maximum Value of x */
  maximum_value_of_x: number;
  /**
   * Minimum Curve Output
   * Specify the minimum value calculated by this curve object
   */
  minimum_curve_output?: number;
  /**
   * Maximum Curve Output
   * Specify the maximum value calculated by this curve object
   */
  maximum_curve_output?: number;
  /**
   * Input Unit Type for X
   * Default: "Dimensionless"
   */
  input_unit_type_for_x?:
    | 'Dimensionless'
    | 'Distance'
    | 'MassFlow'
    | 'Power'
    | 'Pressure'
    | 'Temperature'
    | 'VolumetricFlow';
  /**
   * Output Unit Type
   * Default: "Dimensionless"
   */
  output_unit_type?: 'Capacity' | 'Dimensionless' | 'Power' | 'Pressure' | 'Temperature';
}

