  minimum_curve_output?: number;
  /**
   * Maximum Curve Output
   * Specify the maximum value calculated by this curve object
   */
  maximum_curve_output?: number;
  /**
   * Input Unit Type for w
   * Default: "Dimensionless"
   */
  input_unit_type_for_w?:
    | 'Dimensionless'
    | 'Distance'
    | 'MassFlow'
    | 'Power'
    | 'Temperature'
    | 'VolumetricFlow'
    | 'VolumetricFlowPerPower';
  /**
   * Input Unit Type for x
   * Default: "Dimensionless"
   */
  input_unit_type_for_x?:
    | 'Dimensionless'
    | 'Distance'
    | 'MassFlow'
    | 'Power'
    | 'Temperature'
    | 'VolumetricFlow'
    | 'VolumetricFlowPerPower';
  /**
   * Input Unit Type for y
   * Default: "Dimensionless"
   */
  input_unit_type_for_y?:
    | 'Dimensionless'
    | 'Distance'
    | 'MassFlow'
    | 'Power'
    | 'Temperature'
    | 'VolumetricFlow'
    | 'VolumetricFlowPerPower';
  /**
   * Input Unit Type for z
   * Default: "Dimensionless"
   */
  input_unit_type_for_z?:
    | 'Dimensionless'
    | 'Distance'
    | 'MassFlow'
    | 'Power'
